function t(lang, key) {
  return (UI_STRINGS[lang] && UI_STRINGS[lang][key]) || UI_STRINGS.fr[key] || key;
}
const MEAL_KEYS = ['Petit-déj', 'Déjeuner', 'Dîner', 'Collation'];
const MEAL_LABELS = {
  fr: { 'Petit-déj': 'Petit-déj', 'Déjeuner': 'Déjeuner', 'Dîner': 'Dîner', 'Collation': 'Collation' },
  en: { 'Petit-déj': 'Breakfast', 'Déjeuner': 'Lunch', 'Dîner': 'Dinner', 'Collation': 'Snack' },
  es: { 'Petit-déj': 'Desayuno', 'Déjeuner': 'Comida', 'Dîner': 'Cena', 'Collation': 'Tentempié' }
};
function mealLabel(meal, lang) {
  return (MEAL_LABELS[lang] && MEAL_LABELS[lang][meal]) || meal;
}
const MEAL_TYPE_EMOJIS = { 'Petit-déj': '🔍', 'Déjeuner': '🍽️', 'Dîner': '🍲', 'Collation': '🍎' };
function mealTypeEmoji(meal) {
  return MEAL_TYPE_EMOJIS[meal] || '🍽️';
}


/* ===================== DONNÉES STATIQUES ===================== */
const GOAL_LABELS_META = {
  lose: { emoji: '📉', labelKey: 'goal_lose', descKey: 'goal_lose_d' },
  cut: { emoji: '🔪', labelKey: 'goal_cut', descKey: 'goal_cut_d' },
  maintain: { emoji: '⚖️', labelKey: 'goal_maintain', descKey: 'goal_maintain_d' },
  bulk: { emoji: '📈', labelKey: 'goal_bulk', descKey: 'goal_bulk_d' }
};
function getGoalInfo(goalKey, lang) {
  const meta = GOAL_LABELS_META[goalKey] || GOAL_LABELS_META.maintain;
  return { emoji: meta.emoji, label: t(lang, meta.labelKey), desc: t(lang, meta.descKey) };
}


const DIETARY_RESTRICTIONS_LIST = ['vegetarian', 'vegan', 'lactose', 'gluten', 'nuts', 'fish'];
const HOME_EQUIPMENT_LIST = ['dumbbells', 'bench', 'pullupbar', 'bands', 'abwheel'];
const ACTIVITY_LEVELS_META = [
  { key: 'sedentary', labelKey: 'act_sedentary', descKey: 'act_sedentary_d', factor: 1.2 },
  { key: 'light', labelKey: 'act_light', descKey: 'act_light_d', factor: 1.375 },
  { key: 'moderate', labelKey: 'act_moderate', descKey: 'act_moderate_d', factor: 1.55 },
  { key: 'active', labelKey: 'act_active', descKey: 'act_active_d', factor: 1.725 },
  { key: 'veryactive', labelKey: 'act_veryactive', descKey: 'act_veryactive_d', factor: 1.9 }
];
function getActivityLevels(lang) {
  return ACTIVITY_LEVELS_META.map(a => ({ key: a.key, factor: a.factor, label: t(lang, a.labelKey), desc: t(lang, a.descKey) }));
}


