/* Cherche une icône pour un aliment : d'abord une correspondance exacte dans FOOD_DATABASE
   (la plus fiable), sinon un mot-clé générique (marque ou catégorie), sinon rien (fallback emoji). */
function guessBrandedIcon(name) {
  const n = normalizeForMatch(name || '');
  if (!n) return null;
  const dbMatch = findFoodDbMatch(n);
  if (dbMatch && dbMatch.icon) return dbMatch.icon;
  const match = BRANDED_ICON_MATCHERS.find(m => m.keywords.some(kw => n.includes(kw)));
  return match ? match.icon : null;
}



