function exoLabel(exo, lang) { return (typeof exo === 'string') ? exo : (exo[lang] || exo.fr); }
function exoIcon(exo) { return (typeof exo === 'string') ? null : (exo.icon || null); }
/* Retrouve l'icône illustrée d'un exercice à partir de son seul nom (les séances enregistrées ne
   gardent que le texte, pas la référence à l'icône) — cherche dans toutes les catégories et les
   3 langues, car le nom peut avoir été stocké dans n'importe laquelle. */
function findExerciseIcon(name) {
  if (!name) return null;
  const n = normalizeForMatch(name);
  // Priorité 1 : correspondance exacte.
  for (const cat of Object.values(EXERCISE_DB)) {
    for (const exo of cat.exos) {
      if (typeof exo === 'string' || !exo.icon) continue;
      if (normalizeForMatch(exo.fr) === n || normalizeForMatch(exo.en) === n || normalizeForMatch(exo.es) === n) {
        return exo.icon;
      }
    }
  }
  // Priorité 2 : les programmes générés par l'IA inventent souvent des variantes du nom
  // ("Pompes classiques" au lieu de "Pompes", "Squats au poids du corps" au lieu de "Squat...").
  // On cherche donc aussi une correspondance par mot entier, en gardant la plus proche en longueur.
  let best = null, bestDiff = Infinity;
  for (const cat of Object.values(EXERCISE_DB)) {
    for (const exo of cat.exos) {
      if (typeof exo === 'string' || !exo.icon) continue;
      for (const candidate of [exo.fr, exo.en, exo.es]) {
        const c = normalizeForMatch(candidate);
        if (includesWord(n, c) || includesWord(c, n)) {
          const diff = Math.abs(c.length - n.length);
          if (diff < bestDiff) { best = exo.icon; bestDiff = diff; }
        }
      }
    }
  }
  if (best) return best;
  // Priorité 3 : tolérance au pluriel ("Squats" généré par l'IA vs "Squat" dans notre base) —
  // on retire les "s" finaux isolés de chaque mot avant de comparer.
  const desingularize = s => s.replace(/s(?=\s|$)/g, '');
  const nSing = desingularize(n);
  for (const cat of Object.values(EXERCISE_DB)) {
    for (const exo of cat.exos) {
      if (typeof exo === 'string' || !exo.icon) continue;
      for (const candidate of [exo.fr, exo.en, exo.es]) {
        const c = desingularize(normalizeForMatch(candidate));
        if (includesWord(nSing, c) || includesWord(c, nSing)) {
          const diff = Math.abs(c.length - nSing.length);
          if (diff < bestDiff) { best = exo.icon; bestDiff = diff; }
        }
      }
    }
  }
  if (best) return best;
  // Priorité 4 : en dernier recours, on compare juste le premier mot (le nom du mouvement est
  // presque toujours en tête, ex: "Squat" dans "Squat (flexion des jambes)" et dans "Squats au
  // poids du corps" — même si tout le reste de la phrase diverge). Beaucoup de mouvements
  // différents partagent leur premier mot (ex: "Extension triceps" vs "Extension des jambes" —
  // bras contre jambes !) donc on utilise detectMuscles() pour départager par cohérence
  // musculaire plutôt que la simple proximité de longueur, qui ne veut rien dire ici.
  const muscleToCategory = {
    chest: 'pectoraux', back: 'dos', shoulders: 'epaules', biceps: 'bras', triceps: 'bras',
    arms: 'bras', forearms: 'bras', abs: 'abdos', quads: 'jambes', hamstrings: 'jambes',
    glutes: 'jambes', calves: 'jambes', legs: 'jambes', cardio: 'course', recovery: 'recuperation'
  };
  const detectedEarly = detectMuscles(name);
  const expectedCats = detectedEarly ? detectedEarly.map(m => muscleToCategory[m]).filter(Boolean) : [];
  const firstWord = s => desingularize(s).split(/\s|\(/)[0];
  const nFirst = firstWord(n);
  if (nFirst && nFirst.length >= 3) {
    let bestCategoryMatch = null, bestCategoryDiff = Infinity;
    for (const [catKey, cat] of Object.entries(EXERCISE_DB)) {
      for (const exo of cat.exos) {
        if (typeof exo === 'string' || !exo.icon) continue;
        for (const candidate of [exo.fr, exo.en, exo.es]) {
          const cFirst = firstWord(normalizeForMatch(candidate));
          if (cFirst === nFirst) {
            const diff = Math.abs(normalizeForMatch(candidate).length - n.length);
            // Si on sait à quelle(s) catégorie(s) l'exercice recherché devrait appartenir,
            // on préfère fortement un candidat de cette même catégorie.
            if (expectedCats.length && expectedCats.includes(catKey)) {
              if (diff < bestCategoryDiff) { bestCategoryMatch = exo.icon; bestCategoryDiff = diff; }
            } else if (diff < bestDiff) {
              best = exo.icon; bestDiff = diff;
            }
          }
        }
      }
    }
    if (bestCategoryMatch) return bestCategoryMatch;
  }
  if (best) return best;
  // Priorité 5 : garantie de dernier recours. Si rien n'a matché par le nom, on s'appuie sur
  // detectMuscles() — un classifieur par mots-clés bien plus large (déjà utilisé ailleurs pour
  // deviner les muscles sollicités) — pour retrouver au moins l'icône de la CATÉGORIE de muscle
  // correspondante. Ce n'est pas le mouvement exact, mais ça évite qu'un exercice reste sans
  // aucune image, même avec un nom totalement inédit inventé par l'IA.
  if (detectedEarly && detectedEarly.length) {
    for (const m of detectedEarly) {
      const catKey = muscleToCategory[m];
      if (catKey && EXERCISE_DB[catKey] && EXERCISE_DB[catKey].icon) return EXERCISE_DB[catKey].icon;
    }
  }
  return best;
}
function getExerciseDb(lang) {
  const out = {};
  Object.entries(EXERCISE_DB).forEach(([key, cat]) => {
    out[key] = { emoji: cat.emoji, icon: cat.icon, label: cat.label[lang] || cat.label.fr, exos: cat.exos.map(e => ({ name: exoLabel(e, lang), icon: exoIcon(e) })) };
  });
  return out;
}


const MUSCLE_LABELS = {
  fr: { chest: 'Pectoraux', back: 'Dos', shoulders: 'Épaules', biceps: 'Biceps', triceps: 'Triceps', arms: 'Bras', abs: 'Abdominaux', quads: 'Quadriceps', hamstrings: 'Ischio-jambiers', glutes: 'Fessiers', calves: 'Mollets', legs: 'Jambes', forearms: 'Avant-bras', cardio: 'Cardio / Cœur', fullbody: 'Corps entier' },
  en: { chest: 'Chest', back: 'Back', shoulders: 'Shoulders', biceps: 'Biceps', triceps: 'Triceps', arms: 'Arms', abs: 'Abs', quads: 'Quads', hamstrings: 'Hamstrings', glutes: 'Glutes', calves: 'Calves', legs: 'Legs', forearms: 'Forearms', cardio: 'Cardio / Heart', fullbody: 'Full body' },
  es: { chest: 'Pectorales', back: 'Espalda', shoulders: 'Hombros', biceps: 'Bíceps', triceps: 'Tríceps', arms: 'Brazos', abs: 'Abdominales', quads: 'Cuádriceps', hamstrings: 'Isquiotibiales', glutes: 'Glúteos', calves: 'Pantorrillas', legs: 'Piernas', forearms: 'Antebrazos', cardio: 'Cardio / Corazón', fullbody: 'Cuerpo completo' }
};


const MUSCLE_KEYWORDS = [
  { test: /squat.*bulgare|bulgarian|búlgara/i, muscles: ['quads', 'glutes'] },
  { test: /squat|presse à cuisses|leg press|fente|lunge|zancada|hack squat|sentadilla/i, muscles: ['quads', 'glutes'] },
  { test: /leg curl|ischio|hamstring|isquio|soulevé de terre jambes tendues|romanian deadlift|peso muerto rumano/i, muscles: ['hamstrings', 'glutes'] },
  { test: /leg extension|extensión de cuádriceps|quadriceps|cuádriceps/i, muscles: ['quads'] },
  { test: /soulevé de terre|deadlift|peso muerto/i, muscles: ['back', 'hamstrings', 'glutes'] },
  // Épaules vérifié AVANT la règle pectoraux ci-dessous, sinon "développé militaire"/"développé
  // épaules" se ferait intercepter par le mot générique "développé" et remonterait à tort en pectoraux.
  { test: /développé militaire|military press|press militar|élévation|elevac|face pull|rowing menton|upright row|oiseau|développé épaules|shoulder press|press de hombros/i, muscles: ['shoulders'] },
  { test: /pec deck|écarté|développé|bench press|press de banca|chest press|pompes|push.?up/i, muscles: ['chest', 'triceps'] },
  { test: /tirage|rowing|row|tractions|pull.?up|lat pulldown|jalón|tirón|hyperextension|superman/i, muscles: ['back', 'biceps'] },
  { test: /curl|poulie biceps|biceps pulley/i, muscles: ['biceps'] },
  { test: /triceps|dips|extension.*bras|skullcrusher/i, muscles: ['triceps'] },
  { test: /mollet|calf|pantorrilla/i, muscles: ['calves'] },
  { test: /adducteur|abducteur|adductor|abductor/i, muscles: ['legs'] },
  { test: /crunch|planche|plank|gainage|relevé de jambes|leg raise|elevación de piernas|russian twist|giro ruso|mountain climber|escalador|roue abdominale|ab wheel/i, muscles: ['abs'] },
  { test: /nage|natation|swim|crawl|brasse|papillon|butterfly|mariposa|palmes|piscine|pool|aquagym|aqua fitness/i, muscles: ['cardio'] },
  { test: /footing|fractionné|course|sortie|côtes|run|tapis|treadmill|cinta de correr|vélo|bici|home trainer|cycling|rameur|rowing machine|máquina de remo|elliptique|elliptical|marche|nordique|randonnée|walk|caminat|senderismo|recuperación|récupération active/i, muscles: ['cardio'] },
  { test: /étirement|stretching|estiramiento|^repos$|^rest$|^descanso$|sauna|massage|masaje|cryothérapie|cryotherapy|crioterapia|^yoga$/i, muscles: ['recovery'] }
];


function detectMuscles(exerciseName) {
  for (const entry of MUSCLE_KEYWORDS) {
    if (entry.test.test(exerciseName)) return entry.muscles;
  }
  return null;
}


function defaultRestSeconds(exerciseName, reps) {
  const isCardio = /course|footing|fractionné|vélo|tapis|rameur|elliptique|cinta|bici|cycling|treadmill|marche|walk/i.test(exerciseName || '');
  if (isCardio) return 30;
  const repsNum = parseInt((reps || '10').toString().split('-')[0], 10) || 10;
  if (repsNum <= 6) return 150; // charges lourdes, faibles reps = force
  if (repsNum <= 12) return 75; // hypertrophie classique
  return 45; // endurance musculaire, reps élevées
}


function muscleLabel(key, lang) {
  return (MUSCLE_LABELS[lang] && MUSCLE_LABELS[lang][key]) || (MUSCLE_LABELS.fr[key]) || key;
}


