function searchFoodDatabase(query, lang) {
  lang = lang || 'fr';
  const q = query.trim().toLowerCase();
  const localized = FOOD_DATABASE.map(f => ({ ...f, name: f.name[lang] || f.name.fr, cat: (FOOD_CATEGORIES[lang] || FOOD_CATEGORIES.fr)[f.catKey] }));
  if (!q) return localized;
  return localized.filter(f => f.name.toLowerCase().includes(q) || f.cat.toLowerCase().includes(q));
}


