function supplementBuyLink(query, brand) {
  const q = encodeURIComponent(brand ? `${query} ${brand}` : query);
  return `https://www.google.com/search?tbm=shop&q=${q}`;
}
/* Génère un programme de compléments personnalisé selon l'objectif et le niveau d'activité du profil. */
function generateSupplementProgram(profile, lang) {
  const goal = profile.goal;
  const activity = profile.activity;
  const picks = [];
  const byKey = (k) => SUPPLEMENT_DB.find(s => s.key === k);
  const reason = (fr, en, es) => (lang === 'en' ? en : lang === 'es' ? es : fr);


  picks.push({ ...byKey('whey'), reasonText: reason(
    "Pour boucler ton apport en protéines sans finir la journée à mâcher du poulet froid.",
    "To hit your protein target without ending the day chewing cold chicken.",
    "Para cumplir tu aporte de proteínas sin acabar el día masticando pollo frío.") });


  picks.push({ ...byKey('multivit'), reasonText: reason(
    "Filet de sécurité micronutriments, utile si ton alimentation n'est pas parfaite tous les jours (spoiler : elle ne l'est pas).",
    "Micronutrient safety net, useful since your diet isn't perfect every day (spoiler: it isn't).",
    "Red de seguridad de micronutrientes, útil ya que tu dieta no es perfecta todos los días (spoiler: no lo es).") });


  if (goal === 'bulk' || goal === 'maintain') {
    picks.push({ ...byKey('creatine'), reasonText: reason(
      "Le complément le plus étudié au monde pour la force et la prise de muscle. Pas d'excuse pour s'en passer.",
      "The most studied supplement on earth for strength and muscle gain. No excuse to skip it.",
      "El suplemento más estudiado del mundo para fuerza y ganancia muscular. Sin excusas.") });
  }
  if (goal === 'lose' || goal === 'cut') {
    picks.push({ ...byKey('cafeine'), reasonText: reason(
      "Un coup de boost pour t'entraîner sérieusement même en déficit calorique et fatigue.",
      "A boost to train seriously even in a calorie deficit and fatigue.",
      "Un empujón para entrenar en serio incluso en déficit calórico y con fatiga.") });
  }
  if (activity === 'active' || activity === 'veryactive') {
    picks.push({ ...byKey('omega3'), reasonText: reason(
      "Anti-inflammatoire naturel, utile vu le volume d'entraînement que tu t'infliges.",
      "Natural anti-inflammatory, useful given the training volume you put yourself through.",
      "Antiinflamatorio natural, útil dado el volumen de entrenamiento que te impones.") });
    picks.push({ ...byKey('magnesium'), reasonText: reason(
      "Récupération et sommeil, les deux trucs que tout le monde néglige puis regrette.",
      "Recovery and sleep, the two things everyone neglects and then regrets.",
      "Recuperación y sueño, las dos cosas que todos descuidan y luego lamentan.") });
  }
  return picks;
}


