/* Détecte si un aliment ajouté est plutôt un "plaisir" (fast-food, sucreries, snacks industriels)
   qu'un aliment du quotidien — pour adapter le ton de la phrase du coach en conséquence,
   plutôt qu'une phrase positive aléatoire qui ne colle pas (ex: féliciter pour du Nutella). */
function isTreatFood(item) {
  const name = (item.name || '').toLowerCase();
  if (/nutella|chocolat|chocolate|bonbon|candy|biscuit|cookie|g[âa]teau|cake|glace\b|ice cream|helado|soda|coca[\s-]?cola|chips|donut|beignet|p[âa]tisserie|pastry|barre chocolat|candy bar|confiserie|dulce|nugget|frites|fries|pizza|burger|kebab|rillette/i.test(name)) return true;
  const cal = item.calPer100 || item.calories || 0;
  const protein = item.protein || 0;
  return cal > 350 && protein < 8;
}
function foodAddedVerdict(item, lang) {
  return isTreatFood(item) ? verdict('foodTreat', lang) : verdict('foodGood', lang);
}
function uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }

/* Normalise un texte pour la comparaison floue (minuscules, sans accents). */
function normalizeForMatch(str) {
  return (str || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}
/* Vérifie que `needle` apparaît dans `haystack` comme un mot entier (bordé par un début/fin de
   chaîne ou un caractère non alphanumérique), pas comme simple sous-chaîne. Évite les faux positifs
   du type "oeuf" trouvé à l'intérieur de "boeuf" (b + oeuf) avec un simple .includes(). */
function includesWord(haystack, needle) {
  if (!haystack || !needle) return false;
  const esc = needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(?:^|[^a-z0-9])' + esc + '(?:$|[^a-z0-9])').test(haystack);
}
/* Cherche l'aliment de FOOD_DATABASE correspondant le mieux à un nom libre, en testant les deux
   sens (le nom tapé contient l'aliment, ou l'inverse) mais toujours par mot entier. */
function findFoodDbMatch(n) {
  // Priorité 1 : correspondance exacte (le plus fiable, évite tout risque d'ambiguïté).
  const exact = FOOD_DATABASE.find(f => normalizeForMatch(f.name.fr) === n);
  if (exact) return exact;
  // Priorité 2 : parmi les correspondances par mot entier, on garde celle dont le nom est le
  // plus PROCHE en longueur du texte cherché, plutôt que la première trouvée dans la liste.
  // Sans ça, taper "Pomme" pouvait renvoyer "Pomme de terre cuite" simplement parce que cette
  // entrée arrive avant "Pomme" dans le tableau — même erreur que le bug bœuf/œuf, sous une autre forme.
  let best = null, bestDiff = Infinity;
  FOOD_DATABASE.forEach(f => {
    const dbName = normalizeForMatch(f.name.fr);
    if (includesWord(n, dbName) || includesWord(dbName, n)) {
      const diff = Math.abs(dbName.length - n.length);
      if (diff < bestDiff) { best = f; bestDiff = diff; }
    }
  });
  return best;
}
/* Tente de faire correspondre les articles du placard aux ingrédients d'une recette (texte libre généré par l'IA).
   Retourne les articles du placard qui semblent concernés, avec une quantité à déduire suggérée (extraite du texte
   de l'ingrédient si un nombre est présent, sinon la quantité totale de l'article — on part du principe qu'il est épuisé). */
function matchPantryToIngredients(pantry, ingredients) {
  const ingredientsNorm = (ingredients || []).map(i => normalizeForMatch(i));
  const matches = [];
  (pantry || []).forEach(item => {
    const itemNameNorm = normalizeForMatch(item.name);
    if (!itemNameNorm) return;
    const matchedIngredient = ingredientsNorm.find(ing => ing.includes(itemNameNorm) || itemNameNorm.includes(ing));
    if (!matchedIngredient) return;
    const numMatch = matchedIngredient.match(/(\d+(?:[.,]\d+)?)\s*(g|kg|ml|l)?/);
    let suggestedQty = item.qty;
    if (numMatch) {
      let n = parseFloat(numMatch[1].replace(',', '.'));
      if (numMatch[2] === 'kg' || numMatch[2] === 'l') n *= 1000;
      if (n > 0 && n <= (item.qty || n)) suggestedQty = n;
    }
    matches.push({ item, suggestedQty });
  });
  return matches;
}


function parseJsonLenient(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    // Tentative de réparation : si la réponse a été coupée en plein milieu (limite de tokens atteinte),
    // on retire le dernier élément incomplet et on referme proprement les structures ouvertes.
    let repaired = text;
    // Retire une éventuelle virgule traînante suivie de rien, ou un objet/chaîne incomplet en fin de texte
    repaired = repaired.replace(/,\s*"[^"]*"?\s*:?\s*"?[^"]*$/m, '');
    repaired = repaired.replace(/,\s*\{[^}]*$/m, '');
    repaired = repaired.replace(/,\s*$/m, '');


    const opens = { '{': '}', '[': ']' };
    const stack = [];
    let inString = false;
    let escapeNext = false;
    for (let i = 0; i < repaired.length; i++) {
      const ch = repaired[i];
      if (escapeNext) { escapeNext = false; continue; }
      if (ch === '\\') { escapeNext = true; continue; }
      if (ch === '"') { inString = !inString; continue; }
      if (inString) continue;
      if (ch === '{' || ch === '[') stack.push(ch);
      else if (ch === '}' || ch === ']') stack.pop();
    }
    if (inString) repaired += '"';
    while (stack.length) {
      const open = stack.pop();
      repaired += opens[open];
    }
    try {
      return JSON.parse(repaired);
    } catch (e2) {
      return null;
    }
  }
}


function todayStr() { return new Date().toISOString().slice(0, 10); }
function todayWaterMl(state) {
  const entry = (state.waterLog || []).find(w => w.date === todayStr());
  return entry ? entry.ml : 0;
}
function hydrationGoalMl(state) {
  if (state.settings && state.settings.hydrationGoalMl) return state.settings.hydrationGoalMl;
  const w = state.profile && state.profile.weight;
  return w ? Math.round(w * 35) : 2000;
}
function addWaterMl(setState, amount) {
  setState(s => {
    const date = todayStr();
    const waterLog = [...(s.waterLog || [])];
    const idx = waterLog.findIndex(w => w.date === date);
    if (idx >= 0) waterLog[idx] = { ...waterLog[idx], ml: Math.max(0, waterLog[idx].ml + amount) };
    else waterLog.push({ date, ml: Math.max(0, amount) });
    return { ...s, waterLog };
  });
}
function resetWaterToday(setState) {
  setState(s => {
    const date = todayStr();
    const waterLog = (s.waterLog || []).filter(w => w.date !== date);
    return { ...s, waterLog };
  });
}
/* Coût d'un aliment/repas. Priorité :
   1) Si l'aliment vient de la base FOOD_DATABASE (qty en grammes + price100 connu) : calcul exact
      à partir d'un prix moyen français hors promotion (€/100g).
   2) Sinon (repas manuel, recette IA, article placard sans correspondance) : estimation
      approximative par densité calorique/protéique, étalonnée sur des prix moyens de supermarché. */
function estimateFoodCostEuros(entry) {
  if (entry.price100 != null && entry.qty != null) {
    return Math.max(0, (entry.price100 / 100) * entry.qty);
  }
  const cal = entry.calories || 0, p = entry.protein || 0, c = entry.carbs || 0, f = entry.fat || 0;
  const cost = cal * 0.003 + p * 0.02 + c * 0.002 + f * 0.004;
  return Math.max(0, cost);
}
function mealCostForRange(state, days) {
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - (days - 1));
  const cutoffStr = cutoff.toISOString().slice(0, 10);
  return (state.foodLog || [])
    .filter(f => f.date >= cutoffStr && f.date <= todayStr())
    .reduce((sum, f) => sum + estimateFoodCostEuros(f), 0);
}
function mealCostToday(state) { return mealCostForRange(state, 1); }
function mealCostWeek(state) { return mealCostForRange(state, 7); }
function mealCostMonth(state) { return mealCostForRange(state, 30); }


/* ===================== EXPORT LISTE DE COURSES VERS UN DRIVE ===================== */
function formatShoppingListText(list, lang) {
  const toBuy = (list.items || []).filter(it => !it.haveIt);
  const catLabel = (ck) => (FOOD_CATEGORIES[lang] || FOOD_CATEGORIES.fr)[ck] || ck;
  const grouped = {};
  toBuy.forEach(it => { const k = it.catKey || 'other'; grouped[k] = grouped[k] || []; grouped[k].push(it); });
  let text = (lang === 'en' ? 'Shopping list' : lang === 'es' ? 'Lista de la compra' : 'Liste de courses') + '\n\n';
  Object.entries(grouped).forEach(([ck, its]) => {
    text += `— ${catLabel(ck)} —\n`;
    its.forEach(it => { text += `${it.name}${it.quantity ? ' (' + it.quantity + ')' : ''}\n`; });
    text += '\n';
  });
  return text.trim();
}
async function copyTextToClipboard(text) {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch (e) { /* fallback below */ }
  try {
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.focus(); ta.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    return ok;
  } catch (e) { return false; }
}
function dateLabel(d) {
  const days = ['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'];
  const dt = new Date(d);
  return days[dt.getDay()] + ' ' + dt.getDate() + '/' + (dt.getMonth() + 1);
}


function calcBMR(p) {
  if (!p.weight || !p.height || !p.age) return null;
  let bmr = 10 * p.weight + 6.25 * p.height - 5 * p.age;
  bmr += (p.gender === 'F') ? -161 : 5;
  return bmr;
}
function calcTDEE(p) {
  const bmr = calcBMR(p);
  if (!bmr) return null;
  const level = ACTIVITY_LEVELS_META.find(l => l.key === p.activity);
  return bmr * (level ? level.factor : 1.4);
}
/* IMC = poids(kg) / taille(m)². Catégories OMS standard. */
/* Conversions d'unités : le stockage interne reste toujours en métrique (kg/cm),
   ces fonctions ne servent qu'à l'affichage/saisie quand l'utilisateur préfère lbs/ft-in. */
function kgToLbs(kg) { return Math.round(kg * 2.20462 * 10) / 10; }
function lbsToKg(lbs) { return Math.round((lbs / 2.20462) * 10) / 10; }
function cmToIn(cm) { return Math.round(cm / 2.54); }
function inToCm(inches) { return Math.round(inches * 2.54); }
function formatFeetInches(totalInches) {
  const ft = Math.floor(totalInches / 12), inch = totalInches % 12;
  return `${ft}'${inch}"`;
}
function calcBMI(heightCm, weightKg) {
  if (!heightCm || !weightKg) return null;
  const h = heightCm / 100;
  return weightKg / (h * h);
}
function getBMICategory(bmi, lang) {
  if (bmi == null) return null;
  let key, color;
  if (bmi < 18.5) { key = 'bmi_underweight'; color = '#4d9fff'; }
  else if (bmi < 25) { key = 'bmi_normal'; color = '#4dd67a'; }
  else if (bmi < 30) { key = 'bmi_overweight'; color = '#ffb84d'; }
  else { key = 'bmi_obese'; color = '#e25555'; }
  return { key, color, label: t(lang, key) };
}
function calcTargetCalories(p) {
  const tdee = calcTDEE(p);
  if (!tdee) return null;
  switch (p.goal) {
    case 'lose': return Math.round(tdee - tdee * 0.20);
    case 'cut': return Math.round(tdee - tdee * 0.15);
    case 'bulk': return Math.round(tdee + tdee * 0.12);
    default: return Math.round(tdee);
  }
}
function calcTargetMacros(p, targetCal) {
  let proteinPerKg, fatPct;
  switch (p.goal) {
    case 'lose': proteinPerKg = 2.0; fatPct = 0.25; break;
    case 'cut': proteinPerKg = 2.2; fatPct = 0.22; break;
    case 'bulk': proteinPerKg = 1.8; fatPct = 0.25; break;
    default: proteinPerKg = 1.8; fatPct = 0.28;
  }
  const protein = Math.round(p.weight * proteinPerKg);
  const fat = Math.round((targetCal * fatPct) / 9);
  const carbs = Math.max(0, Math.round((targetCal - protein * 4 - fat * 9) / 4));
  return { protein, carbs, fat };
}


