/* ===================== CARTE MUSCULAIRE (silhouette avant/arrière) ===================== */
/* Illustrations anatomiques réalistes pour le diagramme de muscles sollicités (vue de face / vue de dos). */
const MUSCLE_BODY_FRONT_B64 = "data:image/jpeg;base64,";
const MUSCLE_BODY_BACK_B64 = "data:image/jpeg;base64,";
/* Illustrations anatomiques féminines (vue de face / vue de dos), pour que le diagramme
   corporel s'adapte au genre renseigné dans le profil plutôt que de n'afficher qu'un homme. */
const FEMALE_MUSCLE_BODY_FRONT_B64 = "data:image/jpeg;base64,";
const FEMALE_MUSCLE_BODY_BACK_B64 = "data:image/jpeg;base64,";
/* Zones de muscles positionnées en pourcentage sur les illustrations réalistes (approximatif,
   pas du pixel-perfect anatomique, mais bien plus lisible qu'un dessin géométrique). */
const MUSCLE_ZONES_FRONT = [
  { key: 'shoulders', top: 23, sides: [23, 77], w: 14, h: 8 },
  { key: 'chest', top: 32, sides: [50], w: 34, h: 16 },
  { key: 'abs', top: 46, sides: [50], w: 22, h: 16 },
  { key: 'biceps', top: 38, sides: [15, 85], w: 11, h: 20 },
  { key: 'forearms', top: 62, sides: [11, 89], w: 9, h: 16 },
  { key: 'glutes', top: 55, sides: [50], w: 26, h: 8 },
  { key: 'quads', top: 68, sides: [35, 65], w: 17, h: 20 },
  { key: 'calves', top: 88, sides: [35, 65], w: 12, h: 14 }
];
const MUSCLE_ZONES_BACK = [
  { key: 'shoulders', top: 22, sides: [23, 77], w: 14, h: 8 },
  { key: 'back', top: 33, sides: [50], w: 32, h: 18 },
  { key: 'triceps', top: 38, sides: [15, 85], w: 11, h: 20 },
  { key: 'forearms', top: 62, sides: [11, 89], w: 9, h: 16 },
  { key: 'glutes', top: 51, sides: [50], w: 26, h: 10 },
  { key: 'hamstrings', top: 68, sides: [35, 65], w: 17, h: 18 },
  { key: 'calves', top: 88, sides: [35, 65], w: 12, h: 14 }
];
function MuscleBodyView({ img, zones, isActive }) {
  return (
    <div style={{ position: 'relative', width: 130, flexShrink: 0, background: '#1c1f24', borderRadius: 8, overflow: 'hidden' }}>
      <img src={img} alt="" style={{ width: '100%', display: 'block' }} />
      {zones.map(z => z.sides.map((leftPct, i) => (
        isActive(z.key) && (
          <div key={z.key + i} style={{
            position: 'absolute', top: `${z.top}%`, left: `${leftPct}%`, width: `${z.w}%`, height: `${z.h}%`,
            transform: 'translate(-50%, -50%)', borderRadius: '50%',
            background: '#e2342a', mixBlendMode: 'color', opacity: 0.95
          }} />
        )
      )))}
    </div>
  );
}
function BodyMuscleMap({ muscles, gender }) {
  let active = muscles || [];
  // Décomposition des groupes larges en zones précises
  if (active.includes('legs')) active = [...active, 'quads', 'hamstrings', 'calves', 'glutes'];
  if (active.includes('cardio')) active = [...active, 'quads', 'hamstrings', 'calves'];
  if (active.includes('fullbody') || active.includes('arms')) active = [...active, 'chest', 'back', 'shoulders', 'biceps', 'triceps', 'quads', 'hamstrings', 'abs'];
  const isActive = (m) => active.includes(m);
  const frontImg = gender === 'F' ? FEMALE_MUSCLE_BODY_FRONT_B64 : MUSCLE_BODY_FRONT_B64;
  const backImg = gender === 'F' ? FEMALE_MUSCLE_BODY_BACK_B64 : MUSCLE_BODY_BACK_B64;

  return (
    <div style={{ display: 'flex', gap: 12, justifyContent: 'center', padding: '8px 0' }}>
      <MuscleBodyView img={frontImg} zones={MUSCLE_ZONES_FRONT} isActive={isActive} />
      <MuscleBodyView img={backImg} zones={MUSCLE_ZONES_BACK} isActive={isActive} />
    </div>
  );
}


