      <div style={{ textAlign: 'center', color: '#9aa1ab', fontSize: 13.5, marginBottom: 14 }}>{label}</div>
      {total > 0 && (
        <>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6, fontFamily: "'JetBrains Mono', monospace", fontSize: 12, color: '#7d8590' }}>
            <span>{current} / {total}</span>
            <span>{pct}%</span>
          </div>
          <div style={{ height: 6, borderRadius: 3, background: '#20242a', overflow: 'hidden', marginBottom: 20 }}>
            <div style={{ height: '100%', width: `${pct}%`, background: 'linear-gradient(90deg, #34b483, #1f8f66)', borderRadius: 3, transition: 'width .3s ease' }} />
          </div>
        </>
      )}
      <SkeletonLoader />
