/* Minuteur de jeûne intermittent : presets 16:8 / 18:6 / 20:4 / 12:12.
   Cycle de 24h découpé en phase de jeûne puis fenêtre alimentaire, calculé à partir de l'heure de début. */
const FASTING_PRESETS = ['16:8', '18:6', '20:4', '12:12'];
function fastingPresetHours(preset) {
  const [fastH, eatH] = preset.split(':').map(Number);
  return { fastH: fastH || 0, eatH: eatH || 0 };
}
function formatDuration(ms) {
  const totalMin = Math.max(0, Math.floor(ms / 60000));
  const h = Math.floor(totalMin / 60), m = totalMin % 60;
  return `${h}h${String(m).padStart(2, '0')}`;
}
function FastingCard({ state, setState, toast }) {
  const { lang } = useLang();
  const fasting = state.fasting;
  const [preset, setPreset] = useState((fasting && fasting.preset) || '16:8');
  const [isCustom, setIsCustom] = useState(fasting ? !FASTING_PRESETS.includes(fasting.preset) : false);
  const [customFastH, setCustomFastH] = useState(() => (fasting && !FASTING_PRESETS.includes(fasting.preset)) ? fastingPresetHours(fasting.preset).fastH : 14);
  const [customEatH, setCustomEatH] = useState(() => (fasting && !FASTING_PRESETS.includes(fasting.preset)) ? fastingPresetHours(fasting.preset).eatH : 10);
  const [now, setNow] = useState(Date.now());

  const effectivePreset = isCustom ? `${customFastH}:${customEatH}` : preset;

  useEffect(() => {
    const interval = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(interval);
  }, []);

  const startFast = () => {
    setState(s => ({ ...s, fasting: { preset: effectivePreset, startedAt: new Date().toISOString() } }));
    toast(lang === 'en' ? "Fast started. The fridge is now a museum piece." : lang === 'es' ? "Ayuno iniciado. La nevera ahora es una pieza de museo." : "Jeûne démarré. Le frigo devient une pièce de musée.");
  };
  const endFast = () => {
    setState(s => ({ ...s, fasting: null }));
    toast(lang === 'en' ? "Fast ended." : lang === 'es' ? "Ayuno terminado." : "Jeûne terminé.");
  };

  let phase = null, remainingMs = 0, pct = 0;
  if (fasting) {
    const { fastH, eatH } = fastingPresetHours(fasting.preset);
    const startedAt = new Date(fasting.startedAt).getTime();
    const elapsedMs = now - startedAt;
    const fastMs = fastH * 3600000, cycleMs = (fastH + eatH) * 3600000;
    if (elapsedMs < fastMs) {
      phase = 'fasting'; remainingMs = fastMs - elapsedMs; pct = Math.min(100, Math.round((elapsedMs / fastMs) * 100));
    } else if (elapsedMs < cycleMs) {
      phase = 'eating'; remainingMs = cycleMs - elapsedMs; pct = Math.min(100, Math.round(((elapsedMs - fastMs) / (cycleMs - fastMs)) * 100));
    } else {
      phase = 'done';
    }
  }

  return (
    <Card>
      <CardTitle>⏱ {t(lang, 'fasting_title')}</CardTitle>
      {!fasting && (
        <>
          <div style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 4, marginBottom: 14 }}>
            {FASTING_PRESETS.map(p => (
              <div key={p} onClick={() => { setPreset(p); setIsCustom(false); }} style={{
                flexShrink: 0, padding: '9px 18px', borderRadius: 20, fontSize: 13.5, fontWeight: 700,
                fontFamily: "'JetBrains Mono', monospace", whiteSpace: 'nowrap', cursor: 'pointer',
                background: !isCustom && preset === p ? '#2f9e6e' : '#20242a', color: !isCustom && preset === p ? '#07140f' : '#9aa1ab',
                border: !isCustom && preset === p ? 'none' : '1px solid #34393f', transition: 'background .12s, border-color .12s'
              }}>{p}</div>
            ))}
            <div onClick={() => setIsCustom(true)} style={{
              flexShrink: 0, padding: '9px 18px', borderRadius: 20, fontSize: 13.5, fontWeight: 700,
              fontFamily: "'JetBrains Mono', monospace", whiteSpace: 'nowrap', cursor: 'pointer',
              background: isCustom ? '#2f9e6e' : '#20242a', color: isCustom ? '#07140f' : '#9aa1ab',
              border: isCustom ? 'none' : '1px dashed #34393f', transition: 'background .12s, border-color .12s'
            }}>✎ {t(lang, 'fasting_custom')}</div>
          </div>
          {isCustom && (
            <div style={{ display: 'flex', gap: 10, alignItems: 'flex-end', marginBottom: 14 }}>
              <Field label={t(lang, 'fasting_custom_fast_h')}>
                <input type="number" min="1" max="23" style={inputStyle} value={customFastH} onChange={e => setCustomFastH(Math.max(1, Math.min(23, parseInt(e.target.value) || 1)))} />
              </Field>
              <div style={{ paddingBottom: 12, color: '#7d8590', fontFamily: "'JetBrains Mono', monospace" }}>:</div>
              <Field label={t(lang, 'fasting_custom_eat_h')}>
                <input type="number" min="1" max="23" style={inputStyle} value={customEatH} onChange={e => setCustomEatH(Math.max(1, Math.min(23, parseInt(e.target.value) || 1)))} />
              </Field>
            </div>
          )}
          <Btn block onClick={startFast}>{t(lang, 'fasting_start_btn')}</Btn>
        </>
      )}
      {fasting && phase !== 'done' && (
        <>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', marginBottom: 8 }}>
            <span style={{ fontSize: 12.5, color: '#7d8590', textTransform: 'uppercase', letterSpacing: '0.03em' }}>
              {phase === 'fasting' ? t(lang, 'fasting_phase_fasting') : t(lang, 'fasting_phase_eating')} · {fasting.preset}
            </span>
            <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 20, fontWeight: 700, color: phase === 'fasting' ? '#2f9e6e' : '#5fb87a' }}>
              {formatDuration(remainingMs)}
            </span>
          </div>
          <div style={{ height: 8, borderRadius: 4, background: '#20242a', overflow: 'hidden', marginBottom: 12 }}>
            <div style={{ height: '100%', width: `${pct}%`, background: phase === 'fasting' ? '#2f9e6e' : '#5fb87a', borderRadius: 4, transition: 'width .3s' }} />
          </div>
          <Btn variant="secondary" block onClick={endFast}>{t(lang, 'fasting_end_btn')}</Btn>
        </>
      )}
      {fasting && phase === 'done' && (
        <>
          <p style={{ fontSize: 13, color: '#9aa1ab', marginBottom: 12 }}>{t(lang, 'fasting_cycle_done')}</p>
          <Btn block onClick={startFast}>{t(lang, 'fasting_restart_btn')}</Btn>
        </>
      )}
    </Card>
  );
}


