/* Assemble une semaine de plan alimentaire sans IA, à partir de la banque de recettes statiques,
   mise à l'échelle pour coller approximativement aux calories cibles (répartition 25/35/30/10%). */
function buildOfflineMealPlanWeek(weekNumber, targetCal, lang, restrictions, withSupplements, excludedKeywords, likedKeywords) {
  const shares = { 'Petit-déj': 0.25, 'Déjeuner': 0.35, 'Dîner': 0.30, 'Collation': 0.10 };
  const currentSeason = getCurrentSeason();
  const recipeText = (r) => [
    ...(r.ingredients.fr || []), ...(r.ingredients.en || []), ...(r.ingredients.es || []),
    r.title.fr, r.title.en, r.title.es
  ].join(' ').toLowerCase();
  const avoidDairy = restrictions && (restrictions.includes('lactose') || restrictions.includes('vegan'));
  // Ajout fixe : un laitage + un fruit à chaque déjeuner/dîner, en plus du plat principal (règle nutritionnelle demandée).
  const dairyOptions = {
    fr: ['yaourt', 'yaourt nature', 'fromage blanc', 'un morceau de camembert', 'un morceau de gruyère', 'un morceau de comté', 'un morceau d\'emmental', 'un peu de chèvre', 'un morceau de brie', 'du fromage de brebis', 'un morceau de reblochon', 'un morceau de beaufort', 'un morceau de tomme', 'de la mozzarella', 'un morceau de roquefort', 'un morceau de saint-nectaire', 'du parmesan râpé', 'un morceau de morbier'],
    en: ['yogurt', 'plain yogurt', 'cottage cheese', 'a piece of camembert', 'a piece of cheddar', 'a piece of gouda', 'some goat cheese', 'a piece of brie', 'some mozzarella', 'a piece of blue cheese', 'grated parmesan'],
    es: ['yogur', 'yogur natural', 'requesón', 'un trozo de queso manchego', 'un trozo de queso de cabra', 'un trozo de queso curado', 'un poco de mozzarella', 'un trozo de queso azul', 'parmesano rallado']
  };
  const fruitLabel = { fr: 'fruit', en: 'fruit', es: 'fruta' };
  const days = [];
  for (let d = 1; d <= 7; d++) {
    let usedDairyToday = [];
    const meals = ['Petit-déj', 'Déjeuner', 'Dîner', 'Collation'].map(mealType => {
      const okSupplement = (r) => withSupplements || !r.usesSupplement;
      const okPrefs = (r) => recipeMatchesFreeTextPrefs(r, excludedKeywords);
      const pool = STATIC_RECIPES.filter(r => r.meal === mealType && recipeMatchesRestrictions(r, restrictions) && okSupplement(r) && okPrefs(r));
      const fallbackPool = STATIC_RECIPES.filter(r => recipeMatchesRestrictions(r, restrictions) && okSupplement(r) && okPrefs(r));
      const candidates = pool.length ? pool : (fallbackPool.length ? fallbackPool : STATIC_RECIPES.filter(r => r.meal === mealType));
      const seasonal = candidates.filter(r => r.seasons.includes('toutes') || r.seasons.includes(currentSeason));
      const base = seasonal.length ? seasonal : candidates;
      // Si des aliments "aimés" sont renseignés, privilégie les recettes qui en contiennent au moins un, sans jamais bloquer si aucune ne correspond.
      const liked = (likedKeywords && likedKeywords.length) ? base.filter(r => likedKeywords.some(kw => recipeText(r).includes(kw))) : [];
      const recipe = pick(liked.length ? liked : base);
      const isMainMeal = mealType === 'Déjeuner' || mealType === 'Dîner';
      const addOnKcal = isMainMeal ? (avoidDairy ? 70 : 140) : 0;
      const addOnProtein = isMainMeal ? (avoidDairy ? 1 : 7) : 0;
      const addOnCarbs = isMainMeal ? (avoidDairy ? 16 : 14) : 0;
      const addOnFat = isMainMeal ? (avoidDairy ? 0 : 6) : 0;
      const targetMealCal = (targetCal || 2000) * shares[mealType];
      const mainTargetCal = Math.max(targetMealCal - addOnKcal, targetMealCal * 0.5);
      const scale = recipe.kcal > 0 ? mainTargetCal / recipe.kcal : 1;
      let dairyPick = '';
      if (isMainMeal && !avoidDairy) {
        const pool2 = (dairyOptions[lang] || dairyOptions.fr).filter(o => !usedDairyToday.includes(o));
        dairyPick = pick(pool2.length ? pool2 : (dairyOptions[lang] || dairyOptions.fr));
        usedDairyToday.push(dairyPick);
      }
      const addOnLabel = isMainMeal ? (avoidDairy ? ` + ${fruitLabel[lang] || fruitLabel.fr}` : ` + ${dairyPick} + ${fruitLabel[lang] || fruitLabel.fr}`) : '';
      return {
        type: mealType, name: (recipe.title[lang] || recipe.title.fr) + addOnLabel, emoji: recipe.emoji,
        kcal: Math.round(recipe.kcal * scale) + addOnKcal, protein: Math.round(recipe.protein * scale) + addOnProtein,
        carbs: Math.round(recipe.carbs * scale) + addOnCarbs, fat: Math.round(recipe.fat * scale) + addOnFat
      };
    });
    days.push({ dayNumber: d, meals });
  }
  return { weekNumber, days };
}
function MealPlanWizardModal({ state, setState, closeModal, toast, openModal }) {
  const { lang } = useLang();
  const [weeks, setWeeks] = useState(2);
  const [budget, setBudget] = useState('mid');
  const [eatingPattern, setEatingPattern] = useState(state.fasting ? 'if' : 'normal');
  const [fastingWindow, setFastingWindow] = useState(state.fasting ? state.fasting.preset : '16:8');
  const [withSupplements, setWithSupplements] = useState(false);
  const [likesInput, setLikesInput] = useState(state.profile.foodLikes || '');
  const [dislikesInput, setDislikesInput] = useState(state.profile.foodDislikes || '');
  const [generating, setGenerating] = useState(false);
  const [progress, setProgress] = useState({ current: 0, total: 0 });
  const [error, setError] = useState(null);


  const titleStyle = { fontSize: 20, marginBottom: 16, fontFamily: "'Oswald', sans-serif", fontWeight: 600 };


  const buildWeekPrompt = (weekNumber, p, goalLabel, targetCal, macros, targetWeightLine, prefsLine, startDay = 1, numDays = 7) => {
    const endDay = startDay + numDays - 1;
    const promptByLang = {
      fr: `Crée ${numDays === 7 ? `UNE semaine (semaine ${weekNumber})` : `les jours ${startDay} à ${endDay} de la semaine ${weekNumber}`} d'un plan alimentaire pour une personne avec ce profil :
- Âge: ${p.age} ans, Genre: ${p.gender === 'F' ? 'Femme' : 'Homme'}, Taille: ${p.height}cm, Poids: ${p.weight}kg
- Objectif: ${goalLabel}. ${targetWeightLine}
- Cibles nutritionnelles quotidiennes: ${targetCal} kcal, P${macros.protein}g/G${macros.carbs}g/L${macros.fat}g
- ${prefsLine}

Règle nutritionnelle importante : inclus une source de féculents/glucides complexes (riz, pâtes, pain, pomme de terre, quinoa, légumineuses, avoine...) à CHAQUE repas principal (petit-déjeuner, déjeuner, dîner), y compris en cas de perte de poids ou de sèche — adapte juste la quantité à la baisse plutôt que de les supprimer d'un repas. Ne concentre jamais tous les glucides de la journée sur un seul repas.
Autre règle importante : à CHAQUE déjeuner et CHAQUE dîner, inclus systématiquement un laitage (yaourt, fromage blanc, fromage...) et un fruit, en plus du plat principal — sauf si une restriction (sans lactose, végétalien) l'interdit, auquel cas adapte (laitage végétal, ou fruit seul).

Pour chaque jour concerné (${numDays} jour${numDays > 1 ? 's' : ''}, numérotés de ${startDay} à ${endDay}), propose 4 repas (petit-déjeuner, déjeuner, dîner, collation) réalistes et variés, qui respectent globalement les cibles caloriques/macros journalières (tolérance +/-10%).
Pour chaque repas, liste aussi ses ingrédients avec des quantités précises et réalistes pour UNE personne (ex: "150g de poulet", "80g de riz", "1 yaourt nature"), cohérentes avec les kcal/macros du repas — ces quantités serviront ensuite à générer une liste de courses, donc elles doivent être exactes et complètes (n'oublie aucun ingrédient du plat, y compris les matières grasses de cuisson si notables). Reste concis sur le nombre d'ingrédients (3-5 par repas, l'essentiel seulement).
Réponds UNIQUEMENT en JSON valide, sans markdown, sans préambule, format EXACT (pas de texte avant ou après):
{"days":[{"dayNumber":${startDay},"meals":[{"type":"Petit-déj","name":"nom du repas","emoji":"un seul emoji représentatif du plat","kcal":nombre,"protein":nombre,"carbs":nombre,"fat":nombre,"ingredients":["ingrédient 1 avec quantité","ingrédient 2 avec quantité"]},{"type":"Déjeuner","name":"...","emoji":"...","kcal":0,"protein":0,"carbs":0,"fat":0,"ingredients":["..."]},{"type":"Dîner","name":"...","emoji":"...","kcal":0,"protein":0,"carbs":0,"fat":0,"ingredients":["..."]},{"type":"Collation","name":"...","emoji":"...","kcal":0,"protein":0,"carbs":0,"fat":0,"ingredients":["..."]}]}]}
Génère bien les ${numDays} jour${numDays > 1 ? 's' : ''} complets, avec "dayNumber" allant exactement de ${startDay} à ${endDay} (pas de 1 à ${numDays}). Garde la clé JSON "type" exactement parmi ces 4 chaînes littérales: Petit-déj, Déjeuner, Dîner, Collation. Le champ "name" doit être entièrement en français, court (moins de 8 mots). Le champ "emoji" doit représenter fidèlement l'ingrédient principal du plat. Le champ "ingredients" doit être entièrement en français, au format "quantité + ingrédient".`,
      en: `Create ${numDays === 7 ? `ONE week (week ${weekNumber})` : `days ${startDay} to ${endDay} of week ${weekNumber}`} of a meal plan for a person with this profile:
- Age: ${p.age}, Gender: ${p.gender === 'F' ? 'Female' : 'Male'}, Height: ${p.height}cm, Weight: ${p.weight}kg
- Goal: ${goalLabel}. ${targetWeightLine}
- Daily nutrition targets: ${targetCal} kcal, P${macros.protein}g/C${macros.carbs}g/F${macros.fat}g
- ${prefsLine}

Important nutritional rule: include a starch/complex carb source (rice, pasta, bread, potato, quinoa, legumes, oats...) at EVERY main meal (breakfast, lunch, dinner), even when losing weight or cutting — just reduce the portion rather than removing it from a meal entirely. Never concentrate all of the day's carbs into a single meal.
Another important rule: at EVERY lunch and EVERY dinner, systematically include a dairy product (yogurt, cottage cheese, cheese...) and a fruit, in addition to the main dish — unless a restriction (lactose-free, vegan) forbids it, in which case adapt (plant-based dairy, or fruit only).

For each day involved (${numDays} day${numDays > 1 ? 's' : ''}, numbered ${startDay} to ${endDay}), propose 4 meals (breakfast, lunch, dinner, snack) that are realistic and varied, broadly respecting the daily calorie/macro targets (+/-10% tolerance).
For each meal, also list its ingredients with precise, realistic quantities for ONE person (e.g. "150g chicken breast", "80g rice", "1 plain yogurt"), consistent with the meal's kcal/macros — these quantities will later be used to generate a shopping list, so they must be exact and complete (don't omit any ingredient of the dish, including notable cooking fats). Keep the ingredient count concise (3-5 per meal, the essentials only).
Respond ONLY in valid JSON, no markdown, no preamble, EXACT format (no text before or after):
{"days":[{"dayNumber":${startDay},"meals":[{"type":"Petit-déj","name":"meal name","emoji":"a single emoji representing the dish","kcal":number,"protein":number,"carbs":number,"fat":number,"ingredients":["ingredient 1 with quantity","ingredient 2 with quantity"]},{"type":"Déjeuner","name":"...","emoji":"...","kcal":0,"protein":0,"carbs":0,"fat":0,"ingredients":["..."]},{"type":"Dîner","name":"...","emoji":"...","kcal":0,"protein":0,"carbs":0,"fat":0,"ingredients":["..."]},{"type":"Collation","name":"...","emoji":"...","kcal":0,"protein":0,"carbs":0,"fat":0,"ingredients":["..."]}]}]}
Generate all ${numDays} day${numDays > 1 ? 's' : ''} in full, with "dayNumber" running exactly from ${startDay} to ${endDay} (not 1 to ${numDays}). Keep the JSON key "type" exactly among: Petit-déj, Déjeuner, Dîner, Collation (these 4 literal strings only). The "name" field must be written entirely in English, short (under 8 words). The "emoji" field must faithfully represent the dish's main ingredient. The "ingredients" field must be written entirely in English, in "quantity + ingredient" format.`,
      es: `Crea ${numDays === 7 ? `UNA semana (semana ${weekNumber})` : `los días ${startDay} a ${endDay} de la semana ${weekNumber}`} de un plan alimentario para una persona con este perfil:
- Edad: ${p.age}, Género: ${p.gender === 'F' ? 'Mujer' : 'Hombre'}, Altura: ${p.height}cm, Peso: ${p.weight}kg
- Objetivo: ${goalLabel}. ${targetWeightLine}
- Objetivos nutricionales diarios: ${targetCal} kcal, P${macros.protein}g/C${macros.carbs}g/G${macros.fat}g
- ${prefsLine}

Regla nutricional importante: incluye una fuente de carbohidratos complejos/féculas (arroz, pasta, pan, patata, quinoa, legumbres, avena...) en CADA comida principal (desayuno, comida, cena), incluso en pérdida de peso o definición — simplemente reduce la ración en vez de eliminarla de una comida. Nunca concentres todos los carbohidratos del día en una sola comida.
Otra regla importante: en CADA comida y CADA cena, incluye sistemáticamente un lácteo (yogur, requesón, queso...) y una fruta, además del plato principal — salvo que una restricción (sin lactosa, vegano) lo impida, en cuyo caso adapta (lácteo vegetal, o solo fruta).

Para cada día implicado (${numDays} día${numDays > 1 ? 's' : ''}, numerados del ${startDay} al ${endDay}), propón 4 comidas (desayuno, comida, cena, tentempié) realistas y variadas, respetando en general los objetivos diarios de calorías/macros (tolerancia +/-10%).
Para cada comida, indica también sus ingredientes con cantidades precisas y realistas para UNA persona (ej: "150g de pechuga de pollo", "80g de arroz", "1 yogur natural"), coherentes con las kcal/macros de la comida — estas cantidades se usarán luego para generar una lista de la compra, así que deben ser exactas y completas (no olvides ningún ingrediente del plato, incluidas las grasas de cocción si son notables). Sé conciso con el número de ingredientes (3-5 por comida, solo lo esencial).
Responde SOLO en JSON válido, sin markdown, sin preámbulo, formato EXACTO (sin texto antes o después):
{"days":[{"dayNumber":${startDay},"meals":[{"type":"Petit-déj","name":"nombre de la comida","emoji":"un solo emoji representativo del plato","kcal":número,"protein":número,"carbs":número,"fat":número,"ingredients":["ingrediente 1 con cantidad","ingrediente 2 con cantidad"]},{"type":"Déjeuner","name":"...","emoji":"...","kcal":0,"protein":0,"carbs":0,"fat":0,"ingredients":["..."]},{"type":"Dîner","name":"...","emoji":"...","kcal":0,"protein":0,"carbs":0,"fat":0,"ingredients":["..."]},{"type":"Collation","name":"...","emoji":"...","kcal":0,"protein":0,"carbs":0,"fat":0,"ingredients":["..."]}]}]}
Genera los ${numDays} día${numDays > 1 ? 's' : ''} completos, con "dayNumber" yendo exactamente de ${startDay} a ${endDay} (no de 1 a ${numDays}). Mantén la clave JSON "type" exactamente entre estas 4 cadenas literales: Petit-déj, Déjeuner, Dîner, Collation. El campo "name" debe estar escrito completamente en español, corto (menos de 8 palabras). El campo "emoji" debe representar fielmente el ingrediente principal del plato. El campo "ingredients" debe estar escrito completamente en español, en formato "cantidad + ingrediente".`
    };
    return promptByLang[lang] || promptByLang.fr;
  };


  const buildTitlePrompt = (p, goalLabel) => {
    const promptByLang = {
      fr: `Donne un titre court et un conseil de coach (2-3 phrases, ton direct et un peu cash) pour un plan alimentaire de ${weeks} semaine(s) destiné à une personne dont l'objectif est "${goalLabel}".
Réponds UNIQUEMENT en JSON valide, sans markdown, sans préambule: {"title":"titre court","notes":"conseil du coach"}`,
      en: `Give a short title and a coach's tip (2-3 sentences, direct and a bit blunt tone) for a ${weeks}-week meal plan for a person whose goal is "${goalLabel}".
Respond ONLY in valid JSON, no markdown, no preamble: {"title":"short title","notes":"coach's tip"}`,
      es: `Da un título corto y un consejo de coach (2-3 frases, tono directo y algo cortante) para un plan alimentario de ${weeks} semana(s) para una persona cuyo objetivo es "${goalLabel}".
Responde SOLO en JSON válido, sin markdown, sin preámbulo: {"title":"título corto","notes":"consejo del coach"}`
    };
    return promptByLang[lang] || promptByLang.fr;
  };


  const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));


  const callAI = async (prompt, maxTokens, retries = 4) => {
    let lastErr = null;
    for (let attempt = 0; attempt <= retries; attempt++) {
      try {
        if (attempt > 0) await sleep(Math.min(1000 * Math.pow(2, attempt - 1), 8000));
        const response = await fetch("/api/anthropic", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ model: "claude-sonnet-5", max_tokens: maxTokens, thinking: { type: "disabled" }, messages: [{ role: "user", content: prompt }] })
        });
        if (!response.ok) { lastErr = new Error('http_' + response.status); continue; }
        const data = await response.json();
        if (data.error) { lastErr = new Error('api_error_' + (data.error.message || data.error.type || 'unknown')); continue; }
        const textBlock = data.content && data.content.find(c => c.type === 'text');
        if (!textBlock) { lastErr = new Error('no_text_block'); continue; }
        const clean = textBlock.text.replace(/```json|```/g, '').trim();
        const parsed = parseJsonLenient(clean);
        if (!parsed) { lastErr = new Error('parse_failed'); continue; }
        return parsed;
      } catch (e) {
        lastErr = e;
      }
    }
    throw lastErr || new Error('unknown_error');
  };


  const generate = async () => {
    setGenerating(true); setError(null);
    setProgress({ current: 0, total: weeks * 2 + 1 });
    setState(s => ({ ...s, profile: { ...s.profile, foodLikes: likesInput, foodDislikes: dislikesInput } }));
    const p = state.profile;
    const targetCal = p.targetCalories || 2000;

    if (!state.settings.aiMode) {
      const allWeeks = [];
      for (let w = 1; w <= weeks; w++) {
        allWeeks.push(buildOfflineMealPlanWeek(w, targetCal, lang, state.profile.dietaryRestrictions, withSupplements, splitFoodList(dislikesInput), splitFoodList(likesInput)));
        setProgress({ current: w, total: weeks });
      }
      const staticTitle = lang === 'en' ? 'Preset meal plan' : lang === 'es' ? 'Plan alimentario predefinido' : 'Plan alimentaire préétabli';
      const fullPlan = {
        title: staticTitle, notes: t(lang, 'ai_offline_notice'), weeks: allWeeks, budget, eatingPattern,
        fastingWindow: eatingPattern === 'if' ? fastingWindow : null, withSupplements
      };
      setState(s => ({ ...s, mealPlan: { ...fullPlan, createdAt: todayStr() } }));
      setGenerating(false);
      closeModal();
      if (withSupplements) {
        setTimeout(() => openModal(<SupplementProgramModal state={state} setState={setState} closeModal={closeModal} toast={toast} />), 200);
      }
      return;
    }

    const goalLabel = getGoalInfo(p.goal, lang).label;
    const macros = p.targetMacros || { protein: 0, carbs: 0, fat: 0 };
    const targetWeightLine = (p.goal === 'lose' && p.targetWeight)
      ? (lang === 'en' ? `Target weight: ${p.targetWeight}kg (current: ${p.weight}kg).` : lang === 'es' ? `Peso objetivo: ${p.targetWeight}kg (actual: ${p.weight}kg).` : `Poids objectif: ${p.targetWeight}kg (actuel: ${p.weight}kg).`)
      : '';
    const budgetLabel = { low: t(lang, 'budget_low'), mid: t(lang, 'budget_mid'), high: t(lang, 'budget_high') }[budget];
    const budgetLine = lang === 'en'
      ? (budget === 'low' ? `Monthly grocery budget: ${budgetLabel}. Favor cheap staples (rice, pasta, eggs, chicken thigh, seasonal veg, canned tuna/legumes) and avoid expensive ingredients (salmon, prawns, specialty cheeses) unless occasional.`
        : budget === 'high' ? `Monthly grocery budget: ${budgetLabel}. Feel free to use premium ingredients (salmon, prawns, quality cuts) regularly.`
        : `Monthly grocery budget: ${budgetLabel}. Balanced mix of everyday staples with the occasional pricier ingredient.`)
      : lang === 'es'
      ? (budget === 'low' ? `Presupuesto mensual de compra: ${budgetLabel}. Prioriza alimentos básicos baratos (arroz, pasta, huevos, muslo de pollo, verduras de temporada, atún/legumbres en lata) y evita ingredientes caros (salmón, gambas, quesos especiales) salvo ocasionalmente.`
        : budget === 'high' ? `Presupuesto mensual de compra: ${budgetLabel}. Puedes usar ingredientes premium (salmón, gambas, cortes de calidad) con regularidad.`
        : `Presupuesto mensual de compra: ${budgetLabel}. Mezcla equilibrada de básicos con algún ingrediente más caro de vez en cuando.`)
      : (budget === 'low' ? `Budget courses mensuel: ${budgetLabel}. Privilégie les aliments de base pas chers (riz, pâtes, oeufs, cuisse de poulet, légumes de saison, thon/légumineuses en conserve) et évite les ingrédients coûteux (saumon, crevettes, fromages spéciaux) sauf occasionnellement.`
        : budget === 'high' ? `Budget courses mensuel: ${budgetLabel}. Utilise librement des ingrédients premium (saumon, crevettes, belles pièces de viande) régulièrement.`
        : `Budget courses mensuel: ${budgetLabel}. Mélange équilibré entre aliments du quotidien et quelques ingrédients plus chers de temps en temps.`);
    const scheduleLine = eatingPattern === 'if'
      ? (lang === 'en'
          ? `The person practices intermittent fasting (${fastingWindow} — eating window of ${fastingWindow.split(':')[1]}h). Concentrate all 4 meal slots within that eating window (e.g. for 16:8 roughly between 12pm and 8pm): make "Petit-déj" a light first meal placed at the start of the window (rename it in the "name" field to reflect the real time, e.g. "Premier repas (12h)"), and spread the rest of the daily calories across "Déjeuner", "Collation" and "Dîner" within that same window. Do not suggest anything meant to be eaten outside the window.`
          : lang === 'es'
          ? `La persona practica ayuno intermitente (${fastingWindow} — ventana de alimentación de ${fastingWindow.split(':')[1]}h). Concentra las 4 comidas dentro de esa ventana (ej. para 16:8, aprox. entre las 12h y las 20h): haz que "Petit-déj" sea una primera comida ligera al inicio de la ventana (renómbrala en el campo "name" para reflejar la hora real, ej. "Primera comida (12h)"), y reparte el resto de las calorías diarias entre "Déjeuner", "Collation" y "Dîner" dentro de esa misma ventana. No sugieras nada pensado para comerse fuera de la ventana.`
          : `La personne pratique le jeûne intermittent (${fastingWindow} — fenêtre alimentaire de ${fastingWindow.split(':')[1]}h). Concentre les 4 repas dans cette fenêtre (ex: pour du 16:8, environ entre 12h et 20h) : fais de "Petit-déj" un premier repas léger placé en début de fenêtre (renomme-le dans le champ "name" pour refléter l'heure réelle, ex: "Premier repas (12h)"), et répartis le reste des calories du jour entre "Déjeuner", "Collation" et "Dîner" à l'intérieur de cette même fenêtre. Ne suggère rien de prévu pour être mangé en dehors de la fenêtre.`)
      : '';
    const supplementLine = !withSupplements ? (lang === 'en' ? "No dietary supplements: never use protein powder/whey or any supplement product as a recipe ingredient, only whole real foods." : lang === 'es' ? "Sin suplementos alimenticios: nunca uses proteína en polvo/whey ni ningún producto suplementario como ingrediente, solo alimentos reales." : "Sans compléments alimentaires : n'utilise jamais de whey/protéine en poudre ni aucun produit de complémentation comme ingrédient de recette, uniquement des aliments réels.") : '';
    const dislikesLine = dislikesInput.trim() ? (lang === 'en' ? `STRICT constraint, never violate it under any circumstance: do not use these ingredients/foods at all: ${dislikesInput.trim()}.` : lang === 'es' ? `Restricción ESTRICTA, nunca la incumplas bajo ninguna circunstancia: no uses en absoluto estos ingredientes/alimentos: ${dislikesInput.trim()}.` : `Contrainte STRICTE à respecter absolument, ne l'enfreins jamais : n'utilise jamais ces ingrédients/aliments : ${dislikesInput.trim()}.`) : '';
    const likesLine = likesInput.trim() ? (lang === 'en' ? `Favor these liked ingredients/foods when relevant: ${likesInput.trim()}.` : lang === 'es' ? `Prioriza estos ingredientes/alimentos preferidos cuando tenga sentido: ${likesInput.trim()}.` : `Privilégie ces aliments/ingrédients appréciés quand c'est pertinent : ${likesInput.trim()}.`) : '';
    const prefsLineForWeek = () => [budgetLine, scheduleLine, dietaryRestrictionsPromptLine(state.profile.dietaryRestrictions, lang), supplementLine, dislikesLine, likesLine].filter(Boolean).join(' ');


    let failedStep = 'title';
    try {
      const titleData = await callAI(buildTitlePrompt(p, goalLabel), 500);
      setProgress({ current: 1, total: weeks * 2 + 1 });


      failedStep = 'weeks';
      // L'API refuse un max_tokens trop élevé (erreur http_400) et le modèle peut de toute façon
      // passer une grosse partie de son budget en réflexion interne sur une semaine entière (7 jours
      // x 4 repas x ingrédients) — donc on découpe chaque semaine en 2 appels plus petits (jours 1-4 et
      // 5-7), tous générés EN PARALLÈLE plutôt qu'un par un : ça reste dans le budget de tokens accepté
      // ET c'est nettement plus rapide, surtout sur plusieurs semaines.
      const dayChunks = [];
      for (let w = 1; w <= weeks; w++) {
        dayChunks.push({ w, startDay: 1, numDays: 4 });
        dayChunks.push({ w, startDay: 5, numDays: 3 });
      }
      const chunkOutcomes = await Promise.all(
        dayChunks.map(async ({ w, startDay, numDays }) => {
          try {
            const chunkData = await callAI(buildWeekPrompt(w, p, goalLabel, targetCal, macros, targetWeightLine, prefsLineForWeek(w), startDay, numDays), 8000);
            setProgress(pr => ({ current: pr.current + 1, total: weeks * 2 + 1 }));
            return { w, days: chunkData && chunkData.days };
          } catch (chunkErr) {
            await sleep(3000);
            try {
              const chunkData = await callAI(buildWeekPrompt(w, p, goalLabel, targetCal, macros, targetWeightLine, prefsLineForWeek(w), startDay, numDays), 8000, 1);
              setProgress(pr => ({ current: pr.current + 1, total: weeks * 2 + 1 }));
              return { w, days: chunkData && chunkData.days };
            } catch (finalErr) {
              setProgress(pr => ({ current: pr.current + 1, total: weeks * 2 + 1 }));
              return { w, days: null }; // ce morceau a échoué, on garde le reste
            }
          }
        })
      );
      const avoidDairyAI = state.profile.dietaryRestrictions && (state.profile.dietaryRestrictions.includes('lactose') || state.profile.dietaryRestrictions.includes('vegan'));
      const weekDaysMap = {};
      chunkOutcomes.forEach(({ w, days }) => {
        if (!days || !days.length) return;
        (weekDaysMap[w] || (weekDaysMap[w] = [])).push(...days);
      });
      const allWeeks = Object.keys(weekDaysMap).map(Number).sort((a, b) => a - b)
        .map(w => {
          const sortedDays = weekDaysMap[w].slice().sort((a, b) => (a.dayNumber || 0) - (b.dayNumber || 0));
          return { weekNumber: w, days: enforceMealPlanRules(sortedDays, lang, splitFoodList(dislikesInput), avoidDairyAI) };
        });
      if (allWeeks.length === 0) throw new Error('invalid_week_structure');


      const fullPlan = {
        title: titleData.title || 'Plan alimentaire', notes: titleData.notes || '', weeks: allWeeks, budget, eatingPattern,
        fastingWindow: eatingPattern === 'if' ? fastingWindow : null, withSupplements
      };
      setState(s => ({ ...s, mealPlan: { ...fullPlan, createdAt: todayStr() } }));
      setGenerating(false);
      closeModal();
      if (withSupplements) {
        setTimeout(() => openModal(<SupplementProgramModal state={state} setState={setState} closeModal={closeModal} toast={toast} />), 200);
      }
      if (allWeeks.length < weeks) {
        toast(lang === 'en' ? `Got ${allWeeks.length}/${weeks} weeks, the server choked on the rest. Better than nothing.` : lang === 'es' ? `Conseguí ${allWeeks.length}/${weeks} semanas, el servidor se atascó con el resto. Mejor que nada.` : `J'ai eu ${allWeeks.length}/${weeks} semaines, le serveur a calé sur le reste. Mieux que rien.`);
      } else {
        toast(lang === 'en' ? "Meal plan ready. No more 'I didn't know what to cook'." : lang === 'es' ? "Plan alimentario listo. Se acabó el 'no sabía qué cocinar'." : "Plan alimentaire prêt. Plus d'excuse du genre 'je savais pas quoi cuisiner'.");
      }
    } catch (e) {
      setError(`${t(lang, 'meal_plan_failed')} [${failedStep}: ${e.message || 'unknown'}]`);
      setGenerating(false);
    }
  };


  if (generating) {
    return (
      <>
        <h3 style={titleStyle}>{t(lang, 'meal_plan_generating')}</h3>
        <WizardProgress current={progress.current} total={progress.total} label={t(lang, 'meal_plan_generating_desc')} />
      </>
    );
  }
  if (error) {
    return (
      <>
        <h3 style={titleStyle}>{t(lang, 'failed')}</h3>
        <p style={{ color: '#e25555', fontSize: 14 }}>{error}</p>
        <Btn block style={{ marginTop: 16 }} onClick={closeModal}>{t(lang, 'close')}</Btn>
      </>
    );
  }


  return (
    <>
      <h3 style={titleStyle}>{t(lang, 'meal_plan_wizard_title')}</h3>
      <Field label={t(lang, 'meal_plan_duration_q')}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 8 }}>
          {[1, 2, 4].map(w => (
            <ChoiceCard key={w} label={`${w}`} selected={weeks === w} onClick={() => setWeeks(w)} />
          ))}
        </div>
      </Field>
      <Field label={t(lang, 'meal_plan_budget_q')}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 8 }}>
          {[{ k: 'low', l: t(lang, 'budget_low') }, { k: 'mid', l: t(lang, 'budget_mid') }, { k: 'high', l: t(lang, 'budget_high') }].map(b => (
            <ChoiceCard key={b.k} label={b.l} selected={budget === b.k} onClick={() => setBudget(b.k)} />
          ))}
        </div>
      </Field>
      <Field label={t(lang, 'meal_plan_pattern_q')}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
          {[{ k: 'normal', l: t(lang, 'pattern_normal') }, { k: 'if', l: t(lang, 'pattern_if') }].map(p => (
            <ChoiceCard key={p.k} label={p.l} selected={eatingPattern === p.k} onClick={() => setEatingPattern(p.k)} />
          ))}
        </div>
      </Field>
      {eatingPattern === 'if' && (
        <Field label={t(lang, 'fasting_window_q')}>
          <div style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 4 }}>
            {['16:8', '18:6', '20:4', ...(['16:8', '18:6', '20:4'].includes(fastingWindow) ? [] : [fastingWindow])].map(w => (
              <div key={w} onClick={() => setFastingWindow(w)} style={{
                flexShrink: 0, padding: '9px 18px', borderRadius: 20, fontSize: 13.5, fontWeight: 700,
                fontFamily: "'JetBrains Mono', monospace", whiteSpace: 'nowrap', cursor: 'pointer',
                background: fastingWindow === w ? '#2f9e6e' : '#20242a', color: fastingWindow === w ? '#07140f' : '#9aa1ab',
                border: fastingWindow === w ? 'none' : '1px solid #34393f'
              }}>{w}</div>
            ))}
          </div>
          {state.fasting && state.fasting.preset === fastingWindow && (
            <p style={{ fontSize: 11.5, color: '#7d8590', marginTop: 6, fontStyle: 'italic' }}>{t(lang, 'fasting_window_auto')}</p>
          )}
        </Field>
      )}
      <div style={{ background: '#20242a', border: '1px solid #2e333a', borderRadius: 12, padding: '10px 12px', marginBottom: 14 }}>
        <div style={{ fontSize: 11, color: '#7d8590', fontFamily: "'JetBrains Mono', monospace", textTransform: 'uppercase', marginBottom: 4 }}>🚫 {t(lang, 'dietary_restrictions_title')}</div>
        {(state.profile.dietaryRestrictions || []).length > 0 ? (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
            {state.profile.dietaryRestrictions.map(r => (
              <span key={r} style={{ fontSize: 11.5, padding: '3px 9px', borderRadius: 12, background: '#2f9e6e', color: '#07140f', fontWeight: 600 }}>{t(lang, 'restriction_' + r)}</span>
            ))}
          </div>
        ) : (
          <p style={{ fontSize: 12.5, color: '#7d8590', margin: 0 }}>{t(lang, 'no_restrictions_set')}</p>
        )}
      </div>
      <Field label={t(lang, 'meal_plan_likes_q')}>
        <input style={inputStyle} type="text" placeholder={t(lang, 'meal_plan_likes_ph')} value={likesInput} onChange={e => setLikesInput(e.target.value)} />
      </Field>
      <Field label={t(lang, 'meal_plan_dislikes_q')}>
        <input style={inputStyle} type="text" placeholder={t(lang, 'meal_plan_dislikes_ph')} value={dislikesInput} onChange={e => setDislikesInput(e.target.value)} />
      </Field>
      <Field label={t(lang, 'meal_plan_supplements_q')}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
          <ChoiceCard label={t(lang, 'without_supplements')} selected={!withSupplements} onClick={() => setWithSupplements(false)} />
          <ChoiceCard label={t(lang, 'with_supplements')} selected={withSupplements} onClick={() => setWithSupplements(true)} />
        </div>
      </Field>
      <Btn block onClick={generate}>{t(lang, 'generate_meal_plan')}</Btn>
    </>
  );
}


function MealPlanOverviewModal({ state, setState, closeModal, toast, openModal }) {
  const { lang } = useLang();
  const plan = state.mealPlan;
  const [weekIdx, setWeekIdx] = useState(0);
  const [dayIdx, setDayIdx] = useState(0);
  const week = plan.weeks[weekIdx];
  const day = week.days[dayIdx];


  const plannedMealCost = (m) => estimateFoodCostEuros({ calories: m.kcal, protein: m.protein, carbs: m.carbs, fat: m.fat });
  const fmtEuro = (v) => v.toFixed(2).replace('.', ',') + ' €';
  const dayCost = day.meals.reduce((sum, m) => sum + plannedMealCost(m), 0);
  const weekCost = week.days.reduce((sum, d) => sum + d.meals.reduce((s, m) => s + plannedMealCost(m), 0), 0);
  const planCost = plan.weeks.reduce((sum, w) => sum + w.days.reduce((s, d) => s + d.meals.reduce((s2, m) => s2 + plannedMealCost(m), 0), 0), 0);


  const logThisDay = () => {
    setState(s => ({ ...s, foodLog: [
      ...s.foodLog,
      ...day.meals.map(m => ({ id: uid(), date: todayStr(), time: new Date().toTimeString().slice(0, 5), name: m.name, calories: m.kcal, protein: m.protein, carbs: m.carbs, fat: m.fat, meal: m.type, emoji: mealTypeEmoji(m.type) }))
    ] }));
    closeModal();
    toast(lang === 'en' ? "Day logged. Now go actually cook it." : lang === 'es' ? "Día registrado. Ahora ve a cocinarlo de verdad." : "Journée loggée. Maintenant à toi de vraiment la cuisiner.");
  };


  const regenerate = () => {
    closeModal();
    setTimeout(() => openModal(<MealPlanWizardModal state={state} setState={setState} closeModal={closeModal} toast={toast} openModal={openModal} />), 150);
  };


  return (
    <>
      <h3 style={{ fontSize: 18, marginBottom: 6, fontFamily: "'Oswald', sans-serif", fontWeight: 600 }}>{plan.title}</h3>
      <p style={{ fontSize: 12.5, color: '#7d8590', marginBottom: 16 }}>{plan.weeks.length} {t(lang, 'weeks_count_label')}</p>
      <Verdict text={plan.notes} />

      {plan.withSupplements && (
        <div onClick={() => openModal(<SupplementProgramModal state={state} setState={setState} closeModal={closeModal} toast={toast} />)} style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: '#20242a', border: '1px solid #2e333a',
          borderRadius: 14, padding: '12px 14px', margin: '12px 0', cursor: 'pointer', boxShadow: '0 2px 10px rgba(0,0,0,0.18)'
        }}>
          <span style={{ fontSize: 13, color: '#eef0f2' }}>💊 {t(lang, 'view_supplement_program')}</span>
          <span style={{ color: '#7d8590' }}>›</span>
        </div>
      )}


      <div style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 4, margin: '16px 0 8px' }}>
        {plan.weeks.map((w, i) => (
          <div key={i} onClick={() => { setWeekIdx(i); setDayIdx(0); }} style={{
            flexShrink: 0, padding: '7px 14px', borderRadius: 20, fontSize: 12.5, fontWeight: 600,
            background: weekIdx === i ? '#2f9e6e' : '#20242a', color: weekIdx === i ? '#07140f' : '#9aa1ab',
            border: weekIdx === i ? 'none' : '1px solid #34393f', fontFamily: "'JetBrains Mono', monospace", whiteSpace: 'nowrap', cursor: 'pointer'
          }}>{t(lang, 'meal_plan_week')} {w.weekNumber}</div>
        ))}
      </div>
      <div style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 4, marginBottom: 16 }}>
        {week.days.map((d, i) => (
          <div key={i} onClick={() => setDayIdx(i)} style={{
            flexShrink: 0, padding: '6px 12px', borderRadius: 20, fontSize: 11.5, fontWeight: 600,
            background: dayIdx === i ? '#5fb87a' : '#20242a', color: dayIdx === i ? '#0a0e0a' : '#9aa1ab',
            border: dayIdx === i ? 'none' : '1px solid #34393f', fontFamily: "'JetBrains Mono', monospace", whiteSpace: 'nowrap', cursor: 'pointer'
          }}>{t(lang, 'meal_plan_day')} {d.dayNumber}</div>
        ))}
      </div>


      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 8, marginBottom: 16, background: '#20242a', border: '1px solid #2e333a', borderRadius: 14, boxShadow: '0 2px 10px rgba(0,0,0,0.18)', padding: '10px 8px' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 15, fontWeight: 700 }}>{fmtEuro(dayCost)}</div>
          <div style={{ fontSize: 9.5, color: '#7d8590', textTransform: 'uppercase', letterSpacing: '0.03em', marginTop: 2 }}>{t(lang, 'meal_plan_cost_day')}</div>
        </div>
        <div style={{ textAlign: 'center', borderLeft: '1px solid #34393f', borderRight: '1px solid #34393f' }}>
          <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 15, fontWeight: 700 }}>{fmtEuro(weekCost)}</div>
          <div style={{ fontSize: 9.5, color: '#7d8590', textTransform: 'uppercase', letterSpacing: '0.03em', marginTop: 2 }}>{t(lang, 'meal_plan_cost_week')}</div>
        </div>
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 15, fontWeight: 700, color: '#2f9e6e' }}>{fmtEuro(planCost)}</div>
          <div style={{ fontSize: 9.5, color: '#7d8590', textTransform: 'uppercase', letterSpacing: '0.03em', marginTop: 2 }}>{t(lang, 'meal_plan_cost_total')}</div>
        </div>
      </div>


      {day.meals.map((m, i) => (
        <button key={i} onClick={() => openModal(<MealPlanRecipeModal meal={m} weekIdx={weekIdx} dayIdx={dayIdx} mealIdx={i} state={state} setState={setState} closeModal={closeModal} toast={toast} openModal={openModal} />)} style={{
          display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', textAlign: 'left',
          padding: '12px 14px', marginBottom: 8, borderRadius: 14, background: '#20242a', border: '1px solid #2e333a', boxShadow: '0 2px 8px rgba(0,0,0,0.16)',
          cursor: 'pointer', transition: 'background .12s, border-color .12s'
        }}
        onTouchStart={e => { e.currentTarget.style.background = '#2a2f37'; e.currentTarget.style.borderColor = '#2f9e6e'; }}
        onTouchEnd={e => { e.currentTarget.style.background = '#20242a'; e.currentTarget.style.borderColor = '#34393f'; }}
        onMouseDown={e => { e.currentTarget.style.background = '#2a2f37'; e.currentTarget.style.borderColor = '#2f9e6e'; }}
        onMouseUp={e => { e.currentTarget.style.background = '#20242a'; e.currentTarget.style.borderColor = '#34393f'; }}>
          <div>
            <div style={{ fontSize: 11, color: '#7d8590', fontFamily: "'JetBrains Mono', monospace", textTransform: 'uppercase' }}>{mealLabel(m.type, lang)}</div>
            <div style={{ fontSize: 14, fontWeight: 600, color: '#eef0f2' }}>{m.name}</div>
          </div>
          <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 13, color: '#9aa1ab', textAlign: 'right', flexShrink: 0, marginLeft: 10 }}>{m.kcal} kcal</div>
        </button>
      ))}


      <Btn block style={{ marginTop: 8 }} onClick={logThisDay}>{t(lang, 'log_this_day')}</Btn>
      <Btn variant="secondary" block style={{ marginTop: 8 }} onClick={regenerate}>{t(lang, 'regenerate_meal_plan')}</Btn>
    </>
  );
}


function MealPlanRecipeModal({ meal, weekIdx, dayIdx, mealIdx, state, setState, closeModal, toast, openModal }) {
  const { lang } = useLang();
  const [loading, setLoading] = useState(!meal.detailedRecipe);
  const [recipe, setRecipe] = useState(meal.detailedRecipe || null);
  const [error, setError] = useState(null);


  useEffect(() => {
    if (recipe) return;
    if (!state.settings.aiMode) {
      const found = findStaticRecipeByName(meal.name, lang);
      if (found) {
        setRecipe(found);
        setState(s => {
          const mealPlan = JSON.parse(JSON.stringify(s.mealPlan));
          mealPlan.weeks[weekIdx].days[dayIdx].meals[mealIdx].detailedRecipe = found;
          return { ...s, mealPlan };
        });
      } else {
        setError(t(lang, 'ai_offline_notice'));
      }
      setLoading(false);
      return;
    }
    const run = async () => {
      const mealTypeLabel = mealLabel(meal.type, lang);
      const promptByLang = {
        fr: `Donne-moi la recette détaillée pour ce repas : "${meal.name}" (${mealTypeLabel}, environ ${meal.kcal} kcal, P${meal.protein}g/G${meal.carbs}g/L${meal.fat}g).
Réponds UNIQUEMENT en JSON valide, sans markdown, sans préambule, format exact:
{"ingredients":["ingrédient 1 avec quantité","ingrédient 2 avec quantité"],"steps":["étape 1","étape 2","étape 3"],"time":nombre_minutes}
Les champs "ingredients" et "steps" doivent être entièrement en français.`,
        en: `Give me the detailed recipe for this meal: "${meal.name}" (${mealTypeLabel}, about ${meal.kcal} kcal, P${meal.protein}g/C${meal.carbs}g/F${meal.fat}g).
Respond ONLY in valid JSON, no markdown, no preamble, exact format:
{"ingredients":["ingredient 1 with quantity","ingredient 2 with quantity"],"steps":["step 1","step 2","step 3"],"time":number_minutes}
The "ingredients" and "steps" fields must be written entirely in English, even if the meal name above is in another language.`,
        es: `Dame la receta detallada para esta comida: "${meal.name}" (${mealTypeLabel}, unas ${meal.kcal} kcal, P${meal.protein}g/C${meal.carbs}g/G${meal.fat}g).
Responde SOLO en JSON válido, sin markdown, sin preámbulo, formato exacto:
{"ingredients":["ingrediente 1 con cantidad","ingrediente 2 con cantidad"],"steps":["paso 1","paso 2","paso 3"],"time":número_minutos}
Los campos "ingredients" y "steps" deben estar escritos completamente en español, incluso si el nombre de la comida arriba está en otro idioma.`
      };
      try {
        const response = await fetch("/api/anthropic", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            model: "claude-sonnet-5", max_tokens: 1000, thinking: { type: "disabled" },
            messages: [{ role: "user", content: promptByLang[lang] || promptByLang.fr }]
          })
        });
        const data = await response.json();
        const textBlock = data.content.find(c => c.type === 'text');
        const clean = textBlock.text.replace(/```json|```/g, '').trim();
        const parsed = parseJsonLenient(clean);
        if (!parsed) throw new Error('parse_failed');
        setRecipe(parsed);
        setState(s => {
          const mealPlan = JSON.parse(JSON.stringify(s.mealPlan));
          mealPlan.weeks[weekIdx].days[dayIdx].meals[mealIdx].detailedRecipe = parsed;
          return { ...s, mealPlan };
        });
      } catch (e) {
        setError(lang === 'en' ? "The AI choked on this recipe. Try again." : lang === 'es' ? "La IA se atascó con esta receta. Inténtalo de nuevo." : "L'IA a calé sur cette recette. Réessaie.");
      }
      setLoading(false);
    };
    run();
  }, []);


  const logIt = () => {
    setState(s => ({ ...s, foodLog: [...s.foodLog, {
      id: uid(), date: todayStr(), time: new Date().toTimeString().slice(0, 5),
      name: meal.name, calories: meal.kcal, protein: meal.protein, carbs: meal.carbs, fat: meal.fat,
      meal: meal.type, emoji: mealTypeEmoji(meal.type)
    }] }));
    const matches = (recipe && recipe.ingredients) ? matchPantryToIngredients(state.pantry, recipe.ingredients) : [];
    if (matches.length > 0) {
      openModal(<PantryDeductionModal matches={matches} state={state} setState={setState} closeModal={closeModal} toast={toast} />);
    } else {
      closeModal();
      toast(lang === 'en' ? "Meal logged. Now actually go eat it." : lang === 'es' ? "Comida registrada. Ahora ve a comerla en serio." : "Repas loggé. Maintenant à toi de vraiment le manger.");
    }
  };


  return (
    <>
      <h3 style={{ fontSize: 18, marginBottom: 4, fontFamily: "'Oswald', sans-serif", fontWeight: 600 }}>{meal.name}</h3>
      <div style={{ display: 'flex', gap: 12, fontSize: 11.5, color: '#7d8590', fontFamily: "'JetBrains Mono', monospace", marginBottom: 14 }}>
        <span>🔥 {meal.kcal} kcal</span><span>P{meal.protein}/G{meal.carbs}/L{meal.fat}</span>
        {recipe?.time && <span>⏱ {recipe.time} min</span>}
      </div>
      {loading && <SkeletonLoader label={t(lang, 'ai_searching_pantry')} />}
      {error && <p style={{ color: '#e25555', fontSize: 14 }}>{error}</p>}
      {recipe && (
        <>
          <CardTitle>{t(lang, 'ingredients')}</CardTitle>
          <ul style={{ margin: '0 0 16px', paddingLeft: 18, fontSize: 14, lineHeight: 1.7 }}>
            {(recipe.ingredients || []).map((ing, idx) => <li key={idx}>{ing}</li>)}
          </ul>
          <CardTitle>{t(lang, 'steps')}</CardTitle>
          <ol style={{ margin: 0, paddingLeft: 18, fontSize: 14, lineHeight: 1.7 }}>
            {(recipe.steps || []).map((s, idx) => <li key={idx} style={{ marginBottom: 8 }}>{s}</li>)}
          </ol>
          <Btn block style={{ marginTop: 16 }} onClick={logIt}>{t(lang, 'log_this_meal')}</Btn>
        </>
      )}
    </>
  );
}


