/* ===================== SETTINGS ===================== */
function SettingsView({ state, setState, openModal, closeModal, toast, session, onLogout }) {
  const { lang } = useLang();
  const { profile, settings } = state;
  const goalInfo = getGoalInfo(profile.goal, lang);


  const confirmReset = async () => {
    closeModal();
    try {
      if (session) await supabaseDeleteUserData(session.accessToken, session.user.id);
    } catch (e) {
      // rien à supprimer ou erreur de suppression : on recharge quand même
    }
    window.location.reload();
  };


  const handleLogout = () => {
    closeModal();
    if (onLogout) onLogout();
  };


  return (
    <>
      <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 20 }}>
        <div style={{ width: 60, height: 60, borderRadius: '50%', background: '#262b32', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 26, border: '2px solid #2f9e6e' }}>{goalInfo.emoji}</div>
        <div>
          <h2 style={{ fontSize: 18, margin: 0, fontFamily: "'Oswald', sans-serif", fontWeight: 600 }}>{profile.name || t(lang, 'you')}</h2>
          <div style={{ fontSize: 13, color: '#7d8590' }}>{goalInfo.label} · {profile.age} {t(lang, 'years_old')}</div>
        </div>
      </div>


      <Card>
        <CardTitle>🎛️ Mes axes</CardTitle>
        <p style={{ fontSize: 12.5, color: '#7d8590', lineHeight: 1.4, marginBottom: 10 }}>Choisis ce qui t'intéresse. Les onglets liés à ce que tu décoches disparaissent de l'appli.</p>
        {[
          { key: 'antiGaspi', label: t(lang, 'modules_antigaspi_label'), desc: t(lang, 'modules_antigaspi_desc') },
          { key: 'plan', label: t(lang, 'modules_plan_label'), desc: t(lang, 'modules_plan_desc') },
          { key: 'sport', label: t(lang, 'modules_sport_label'), desc: t(lang, 'modules_sport_desc') }
        ].map(m => {
          const mods = settings.modules || DEFAULT_MODULES;
          const active = !!mods[m.key];
          const isLastActive = active && Object.values(mods).filter(Boolean).length <= 1;
          return (
            <div key={m.key} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 0', borderTop: '1px solid #262b32' }}>
              <div style={{ paddingRight: 12 }}>
                <div style={{ fontSize: 13.5, fontWeight: 600 }}>{m.label}</div>
                <div style={{ fontSize: 11.5, color: '#7d8590', marginTop: 2 }}>{m.desc}</div>
              </div>
              <div
                onClick={() => {
                  if (isLastActive) { toast(t(lang, 'modules_pick_one')); return; }
                  setState(s => ({ ...s, settings: { ...s.settings, modules: { ...(s.settings.modules || DEFAULT_MODULES), [m.key]: !active } } }));
                }}
                style={{
                  width: 46, height: 26, borderRadius: 15, background: active ? '#2f9e6e' : '#34393f',
                  position: 'relative', cursor: 'pointer', flexShrink: 0, transition: 'background .15s',
                  opacity: isLastActive ? 0.6 : 1
                }}
              >
                <div style={{
                  width: 20, height: 20, borderRadius: '50%', background: '#fff', position: 'absolute', top: 3,
                  left: active ? 23 : 3, transition: 'left .15s', boxShadow: '0 1px 3px rgba(0,0,0,0.3)'
                }} />
              </div>
            </div>
          );
        })}
      </Card>


      <Card>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
          <CardTitle style={{ marginBottom: 0 }}>🤖 {t(lang, 'ai_mode_title')}</CardTitle>
          <span style={{
            fontSize: 11, fontWeight: 700, padding: '4px 10px', borderRadius: 12, fontFamily: "'JetBrains Mono', monospace",
            background: settings.aiMode ? 'rgba(47,158,110,0.15)' : 'rgba(125,133,144,0.15)', color: settings.aiMode ? '#2f9e6e' : '#9aa1ab'
          }}>{settings.aiMode ? t(lang, 'ai_status_on') : t(lang, 'ai_status_off')}</span>
        </div>
        <p style={{ fontSize: 12.5, color: '#7d8590', lineHeight: 1.4 }}>
          {settings.aiMode ? t(lang, 'ai_mode_on_desc') : t(lang, 'ai_mode_off_desc')}
        </p>
        <p style={{ fontSize: 11, color: '#5c636e', lineHeight: 1.4, marginTop: 8, fontStyle: 'italic' }}>{t(lang, 'ai_mode_auto_note')}</p>
      </Card>


      <Card>
        <CardTitle>🚫 {t(lang, 'dietary_restrictions_title')}</CardTitle>
        <p style={{ fontSize: 12.5, color: '#7d8590', lineHeight: 1.4, marginBottom: 10 }}>{t(lang, 'dietary_restrictions_desc')}</p>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
          {DIETARY_RESTRICTIONS_LIST.map(key => {
            const active = (profile.dietaryRestrictions || []).includes(key);
            return (
              <div key={key} onClick={() => {
                const current = profile.dietaryRestrictions || [];
                const next = active ? current.filter(r => r !== key) : [...current, key];
                setState(s => ({ ...s, profile: { ...s.profile, dietaryRestrictions: next } }));
              }} style={{
                padding: '7px 12px', borderRadius: 20, fontSize: 12.5, fontWeight: 600, cursor: 'pointer',
                background: active ? '#2f9e6e' : '#20242a', color: active ? '#07140f' : '#9aa1ab',
                border: active ? 'none' : '1px solid #34393f', fontFamily: "'JetBrains Mono', monospace"
              }}>{t(lang, 'restriction_' + key)}</div>
            );
          })}
        </div>
      </Card>


      <Card>
        <CardTitle>{t(lang, 'profile')}</CardTitle>
        {[
          [t(lang, 'height_label'), `${profile.height} cm`], [t(lang, 'current_weight'), `${profile.weight} kg`], [t(lang, 'goal'), goalInfo.label],
          ...(profile.goal === 'lose' && profile.targetWeight ? [[t(lang, 'target_weight_label'), `${profile.targetWeight} kg`]] : []),
          [t(lang, 'activity'), profile.activity], [t(lang, 'target_calories'), `${profile.targetCalories || '—'} kcal`]
        ].map(([k, v], i) => (
          <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '14px 0', borderBottom: '1px solid #34393f' }}>
            <span style={{ fontSize: 14 }}>{k}</span><span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 13, color: '#9aa1ab' }}>{v}</span>
          </div>
        ))}
        <Btn variant="secondary" block style={{ marginTop: 12 }} onClick={() => openModal(<EditProfileModal state={state} setState={setState} closeModal={closeModal} toast={toast} />)}>{t(lang, 'edit_profile')}</Btn>
      </Card>


      <Card>
        <CardTitle>{t(lang, 'notif_settings_title')}</CardTitle>
        <p style={{ fontSize: 12.5, color: '#7d8590', marginBottom: 12 }}>{t(lang, 'notif_settings_desc')}</p>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '14px 0' }}>
          <span style={{ fontSize: 14 }}>{t(lang, 'notif_enable')}</span>
          <div onClick={async () => {
            if (!state.settings.notifsEnabled) {
              if (typeof Notification !== 'undefined') {
                const perm = await Notification.requestPermission();
                if (perm !== 'granted') { toast(t(lang, 'notif_permission_denied')); return; }
              }
              setState(s => ({ ...s, settings: { ...s.settings, notifsEnabled: true } }));
            } else {
              setState(s => ({ ...s, settings: { ...s.settings, notifsEnabled: false } }));
            }
          }} style={{
            width: 46, height: 26, borderRadius: 14, background: state.settings.notifsEnabled ? '#2f9e6e' : '#34393f',
            position: 'relative', cursor: 'pointer', transition: 'background .15s', flexShrink: 0
          }}>
            <div style={{
              width: 20, height: 20, borderRadius: '50%', background: '#eef0f2', position: 'absolute', top: 3,
              left: state.settings.notifsEnabled ? 23 : 3, transition: 'left .15s'
            }} />
          </div>
        </div>
      </Card>


      {session && (
        <Card>
          <CardTitle>Compte</CardTitle>
          <p style={{ fontSize: 13, color: '#9aa1ab', marginBottom: 14 }}>Connecté en tant que <strong>{session.user?.email}</strong></p>
          <Btn variant="secondary" block onClick={handleLogout}>Se déconnecter</Btn>
        </Card>
      )}


      <Card>
        <CardTitle>{t(lang, 'data')}</CardTitle>
        <Btn variant="danger" block onClick={() => openModal(
          <>
            <h3 style={{ fontSize: 19, marginBottom: 16, fontFamily: "'Oswald', sans-serif", fontWeight: 600 }}>{t(lang, 'confirm_reset_title')}</h3>
            <p style={{ fontSize: 14, color: '#9aa1ab', marginBottom: 18 }}>{t(lang, 'confirm_reset_desc')}</p>
            <div style={{ display: 'flex', gap: 10 }}>
              <Btn variant="ghost" onClick={closeModal} style={{ flex: 1 }}>{t(lang, 'cancel')}</Btn>
              <Btn variant="danger" onClick={confirmReset} style={{ flex: 1 }}>{t(lang, 'confirm_delete_all')}</Btn>
            </div>
          </>
        )}>{t(lang, 'reset_all')}</Btn>
      </Card>
    </>
  );
}


function EditProfileModal({ state, setState, closeModal, toast }) {
  const { lang } = useLang();
  const { profile, settings } = state;
  const [units, setUnitsRaw] = useState(settings.units || 'metric');
  const isImperial = units === 'imperial';
  const [name, setName] = useState(profile.name || '');
  const [age, setAge] = useState(profile.age || '');
  const [height, setHeight] = useState(profile.height ? (isImperial ? cmToIn(profile.height) : profile.height) : '');
  const [weight, setWeight] = useState(profile.weight ? (isImperial ? kgToLbs(profile.weight) : profile.weight) : '');
  const [goal, setGoal] = useState(profile.goal);
  const [activity, setActivity] = useState(profile.activity);
  const [targetWeight, setTargetWeight] = useState(profile.targetWeight ? (isImperial ? kgToLbs(profile.targetWeight) : profile.targetWeight) : '');

  // Convertit les valeurs affichées quand on bascule l'unité, pour que les nombres restent cohérents.
  const setUnits = (newUnits) => {
    if (newUnits === units) return;
    const toImperial = newUnits === 'imperial';
    setHeight(h => h === '' ? '' : (toImperial ? cmToIn(parseFloat(h)) : inToCm(parseFloat(h))));
    setWeight(w => w === '' ? '' : (toImperial ? kgToLbs(parseFloat(w)) : lbsToKg(parseFloat(w))));
    setTargetWeight(tw => tw === '' ? '' : (toImperial ? kgToLbs(parseFloat(tw)) : lbsToKg(parseFloat(tw))));
    setUnitsRaw(newUnits);
  };

  const save = () => {
    setState(s => {
      const heightCm = height ? (isImperial ? inToCm(parseFloat(height)) : parseFloat(height)) : s.profile.height;
      const newWeight = weight ? (isImperial ? lbsToKg(parseFloat(weight)) : parseFloat(weight)) : s.profile.weight;
      const newTargetWeight = targetWeight ? (isImperial ? lbsToKg(parseFloat(targetWeight)) : parseFloat(targetWeight)) : s.profile.targetWeight;
      const weightHistory = newWeight !== s.profile.weight
        ? [...s.profile.weightHistory, { date: todayStr(), weight: newWeight }]
        : s.profile.weightHistory;
      const newProfile = {
        ...s.profile, name: name.trim(), age: parseInt(age) || s.profile.age, height: heightCm || s.profile.height,
        weight: newWeight, weightHistory, goal, activity, targetWeight: goal === 'lose' ? newTargetWeight : s.profile.targetWeight
      };
      const cal = calcTargetCalories(newProfile);
      if (cal) { newProfile.targetCalories = cal; newProfile.targetMacros = calcTargetMacros(newProfile, cal); }
      return { ...s, profile: newProfile, settings: { ...s.settings, units } };
    });
    closeModal();
    toast(lang === 'en' ? "Profile updated. We'll see if you keep your word this time." : lang === 'es' ? "Perfil actualizado. Veremos si cumples tu palabra esta vez." : "Profil mis à jour. On verra si tu tiens parole cette fois.");
  };


  return (
    <>
      <h3 style={{ fontSize: 19, marginBottom: 16, fontFamily: "'Oswald', sans-serif", fontWeight: 600 }}>{t(lang, 'edit_profile')}</h3>
      <Field label={t(lang, 'units_q')}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
          <ChoiceCard label={t(lang, 'units_metric')} selected={units === 'metric'} onClick={() => setUnits('metric')} />
          <ChoiceCard label={t(lang, 'units_imperial')} selected={units === 'imperial'} onClick={() => setUnits('imperial')} />
        </div>
      </Field>
      <Field label={t(lang, 'first_name')}><input style={inputStyle} type="text" value={name} onChange={e => setName(e.target.value)} /></Field>
      <Field label={t(lang, 'age')}><input style={inputStyle} type="number" value={age} onChange={e => setAge(e.target.value)} /></Field>
      <Field label={`${t(lang, 'onboard_height')} ${isImperial ? '(in)' : ''}`}><input style={inputStyle} type="number" value={height} onChange={e => setHeight(e.target.value)} /></Field>
      <Field label={`${t(lang, 'onboard_weight')} ${isImperial ? '(lbs)' : ''}`}><input style={inputStyle} type="number" step={isImperial ? '1' : '0.1'} value={weight} onChange={e => setWeight(e.target.value)} /></Field>
      <Field label={t(lang, 'goal')}>
        <select style={inputStyle} value={goal} onChange={e => setGoal(e.target.value)}>
          {Object.keys(GOAL_LABELS_META).map(k => { const g = getGoalInfo(k, lang); return <option key={k} value={k}>{g.emoji} {g.label}</option>; })}
        </select>
      </Field>
      {goal === 'lose' && (
        <Field label={t(lang, 'target_weight_label')}>
          <input style={inputStyle} type="number" step={isImperial ? '1' : '0.1'} placeholder={t(lang, 'target_weight_ph')} value={targetWeight} onChange={e => setTargetWeight(e.target.value)} />
        </Field>
      )}
      <BMIBlock height={height ? (isImperial ? inToCm(parseFloat(height)) : parseFloat(height)) : null} weight={weight ? (isImperial ? lbsToKg(parseFloat(weight)) : parseFloat(weight)) : null} goal={goal} targetWeight={targetWeight ? (isImperial ? lbsToKg(parseFloat(targetWeight)) : parseFloat(targetWeight)) : null} lang={lang} />
      <Field label={t(lang, 'activity_level')}>
        <select style={inputStyle} value={activity} onChange={e => setActivity(e.target.value)}>
          {getActivityLevels(lang).map(l => <option key={l.key} value={l.key}>{l.label}</option>)}
        </select>
      </Field>
      <Btn block onClick={save}>{t(lang, 'save')}</Btn>
    </>
  );
}


/* ===================== APP ROOT ===================== */
const initialState = {
  profile: { name: '', age: null, height: null, weight: null, weightHistory: [], goal: null, activity: 'moderate', gender: 'F', targetCalories: null, targetMacros: null, targetWeight: null, dietaryRestrictions: [], foodLikes: '', foodDislikes: '', modules: { ...EMPTY_MODULES } },
  pantry: [], foodLog: [], recipes: [], workouts: [], supplementLog: [], waterLog: [],
  settings: { notifsEnabled: false, aiMode: true, units: 'metric', weeklyWorkoutGoal: 3, modules: { ...DEFAULT_MODULES } },
  trainingProgram: null,
  measurements: [],
  mealPlan: null,
  fasting: null,
  challenge: null,
  shoppingList: null,
  progressPhotos: []
};


const STORAGE_KEY = 'croquefit-data';

/* ===================== SUPABASE ===================== */
const SUPABASE_URL = 'https://uhkbjdwzwmrdjcojmiop.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable_kPvW-kZfPBJy0GVAw4CpJw_b3aUeG3L';

async function supabaseSignUp(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/signup`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', apikey: SUPABASE_ANON_KEY },
    body: JSON.stringify({ email, password })
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.msg || data.error_description || data.error || 'Erreur inscription');
  return data;
}

async function supabaseSignIn(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', apikey: SUPABASE_ANON_KEY },
    body: JSON.stringify({ email, password })
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.msg || data.error_description || data.error || 'Erreur connexion');
  return data;
}

async function supabaseRefreshSession(refreshToken) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', apikey: SUPABASE_ANON_KEY },
    body: JSON.stringify({ refresh_token: refreshToken })
  });
  const data = await res.json();
  if (!res.ok) throw new Error('Session expirée');
  return data;
}

async function supabaseRequestPasswordReset(email) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/recover`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', apikey: SUPABASE_ANON_KEY },
    body: JSON.stringify({ email, redirect_to: window.location.origin })
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.msg || data.error_description || data.error || 'Erreur lors de la demande de réinitialisation');
  }
}

async function supabaseUpdatePassword(accessToken, newPassword) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json', apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${accessToken}`
    },
    body: JSON.stringify({ password: newPassword })
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.msg || data.error_description || data.error || 'Erreur mise à jour du mot de passe');
  return data;
}

const SESSION_STORAGE_KEY = 'croquefit-session';

function saveSessionToStorage(session) {
  try {
    if (session) localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session));
    else localStorage.removeItem(SESSION_STORAGE_KEY);
  } catch (e) { /* localStorage indisponible : session simplement non persistée */ }
}

function loadSessionFromStorage() {
  try {
    const raw = localStorage.getItem(SESSION_STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) { return null; }
}

async function supabaseFetchUserData(accessToken, userId) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/user_data?user_id=eq.${userId}&select=*`, {
    headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${accessToken}` }
  });
  if (!res.ok) throw new Error('Erreur chargement des données');
  const rows = await res.json();
  return rows && rows.length ? rows[0] : null;
}

async function supabaseCreateUserRow(accessToken, userId) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/user_data`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json', apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${accessToken}`, Prefer: 'return=representation'
    },
    body: JSON.stringify({ user_id: userId })
  });
  if (!res.ok) throw new Error('Erreur création profil');
  const rows = await res.json();
  return rows && rows.length ? rows[0] : null;
}

async function supabaseSaveUserData(accessToken, userId, payload) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/user_data?user_id=eq.${userId}`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json', apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${accessToken}`, Prefer: 'return=minimal'
    },
    body: JSON.stringify(payload)
  });
  return res.ok;
}

async function supabaseDeleteUserData(accessToken, userId) {
  await fetch(`${SUPABASE_URL}/rest/v1/user_data?user_id=eq.${userId}`, {
    method: 'DELETE',
    headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${accessToken}` }
  });
}

/* ===================== ÉCRAN DE CONNEXION ===================== */
function AuthScreen({ onAuthenticated }) {
  const [mode, setMode] = useState('login'); // 'login' | 'signup' | 'forgot'
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPw, setConfirmPw] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [info, setInfo] = useState('');

  const submit = async () => {
    setError(''); setInfo('');

    if (mode === 'forgot') {
      if (!email) { setError("Renseigne ton email."); return; }
      setLoading(true);
      try {
        await supabaseRequestPasswordReset(email);
        setInfo("Si un compte existe avec cet email, un lien de réinitialisation vient d'être envoyé. Vérifie ta boîte mail (et tes spams).");
      } catch (e) {
        setError(e.message || "Une erreur est survenue.");
      } finally {
        setLoading(false);
      }
      return;
    }

    if (!email || !password) { setError("Renseigne ton email et ton mot de passe."); return; }
    if (mode === 'signup' && password !== confirmPw) { setError("Les mots de passe ne correspondent pas."); return; }
    if (password.length < 6) { setError("Le mot de passe doit faire au moins 6 caractères."); return; }
    setLoading(true);
    try {
      if (mode === 'signup') {
        const data = await supabaseSignUp(email, password);
        if (data.access_token) {
          onAuthenticated({ accessToken: data.access_token, refreshToken: data.refresh_token, user: data.user });
        } else {
          setInfo("Compte créé ! Si la confirmation par email est activée, vérifie ta boîte mail puis connecte-toi.");
          setMode('login');
        }
      } else {
        const data = await supabaseSignIn(email, password);
        onAuthenticated({ accessToken: data.access_token, refreshToken: data.refresh_token, user: data.user });
      }
    } catch (e) {
      setError(e.message || "Une erreur est survenue.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: "'Inter', system-ui, sans-serif", background: 'radial-gradient(circle at 50% 0%, rgba(47,158,110,0.08), transparent 45%), #131519',
      color: '#eef0f2', minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24, boxSizing: 'border-box'
    }}>
      <style>{`
        * { box-sizing: border-box; }
        input::placeholder { color: #7d8590; }
        .btn-press:active { transform: scale(0.97); }
      `}</style>
      <div style={{ width: '100%', maxWidth: 380 }}>
        <div style={{ textAlign: 'center', marginBottom: 28 }}>
          <div style={{ fontFamily: "'Oswald', sans-serif", fontSize: 32, fontWeight: 700, letterSpacing: '0.02em' }}>
            Eat<span style={{ color: '#2f9e6e' }}>Fit</span>
          </div>
          <div style={{ fontSize: 13, color: '#7d8590', marginTop: 6 }}>
            {mode === 'login' ? 'Connecte-toi pour continuer' : mode === 'signup' ? 'Crée ton compte' : 'Réinitialiser ton mot de passe'}
          </div>
        </div>

        <Card>
          <Field label="Email">
            <input style={inputStyle} type="email" autoCapitalize="none" placeholder="ton@email.com" value={email} onChange={e => setEmail(e.target.value)} />
          </Field>
          {mode !== 'forgot' && (
            <Field label="Mot de passe">
              <input style={inputStyle} type="password" placeholder="••••••••" value={password} onChange={e => setPassword(e.target.value)} />
            </Field>
          )}
          {mode === 'signup' && (
            <Field label="Confirme le mot de passe">
              <input style={inputStyle} type="password" placeholder="••••••••" value={confirmPw} onChange={e => setConfirmPw(e.target.value)} />
            </Field>
          )}
          {mode === 'login' && (
            <div style={{ textAlign: 'right', marginBottom: 14, marginTop: -6 }}>
              <span style={{ color: '#7d8590', cursor: 'pointer', fontSize: 12.5, textDecoration: 'underline' }}
                onClick={() => { setMode('forgot'); setError(''); setInfo(''); }}>Mot de passe oublié ?</span>
            </div>
          )}
          {error && <div style={{ color: '#e25555', fontSize: 13, marginBottom: 14 }}>{error}</div>}
          {info && <div style={{ color: '#2f9e6e', fontSize: 13, marginBottom: 14 }}>{info}</div>}
          <Btn block onClick={submit} disabled={loading}>
            {loading ? 'Un instant…' : (mode === 'login' ? 'Se connecter' : mode === 'signup' ? "S'inscrire" : 'Envoyer le lien')}
          </Btn>
        </Card>

        <div style={{ textAlign: 'center', fontSize: 13, color: '#7d8590' }}>
          {mode === 'login' ? (
            <>Pas encore de compte ?{' '}
              <span style={{ color: '#2f9e6e', cursor: 'pointer', fontWeight: 600 }} onClick={() => { setMode('signup'); setError(''); setInfo(''); }}>S'inscrire</span>
            </>
          ) : mode === 'signup' ? (
            <>Déjà un compte ?{' '}
              <span style={{ color: '#2f9e6e', cursor: 'pointer', fontWeight: 600 }} onClick={() => { setMode('login'); setError(''); setInfo(''); }}>Se connecter</span>
            </>
          ) : (
            <span style={{ color: '#2f9e6e', cursor: 'pointer', fontWeight: 600 }} onClick={() => { setMode('login'); setError(''); setInfo(''); }}>Retour à la connexion</span>
          )}
        </div>
      </div>
    </div>
  );
}

function PasswordResetScreen({ accessToken, onDone }) {
  const [password, setPassword] = useState('');
  const [confirmPw, setConfirmPw] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const submit = async () => {
    setError('');
    if (password.length < 6) { setError("Le mot de passe doit faire au moins 6 caractères."); return; }
    if (password !== confirmPw) { setError("Les mots de passe ne correspondent pas."); return; }
    setLoading(true);
    try {
      await supabaseUpdatePassword(accessToken, password);
      onDone();
    } catch (e) {
      setError(e.message || "Une erreur est survenue.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: "'Inter', system-ui, sans-serif", background: 'radial-gradient(circle at 50% 0%, rgba(47,158,110,0.08), transparent 45%), #131519',
      color: '#eef0f2', minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24, boxSizing: 'border-box'
    }}>
      <div style={{ width: '100%', maxWidth: 380 }}>
        <div style={{ textAlign: 'center', marginBottom: 28 }}>
          <div style={{ fontFamily: "'Oswald', sans-serif", fontSize: 32, fontWeight: 700, letterSpacing: '0.02em' }}>
            Eat<span style={{ color: '#2f9e6e' }}>Fit</span>
          </div>
          <div style={{ fontSize: 13, color: '#7d8590', marginTop: 6 }}>Choisis un nouveau mot de passe</div>
        </div>
        <Card>
          <Field label="Nouveau mot de passe">
            <input style={inputStyle} type="password" placeholder="••••••••" value={password} onChange={e => setPassword(e.target.value)} />
          </Field>
          <Field label="Confirme le nouveau mot de passe">
            <input style={inputStyle} type="password" placeholder="••••••••" value={confirmPw} onChange={e => setConfirmPw(e.target.value)} />
          </Field>
          {error && <div style={{ color: '#e25555', fontSize: 13, marginBottom: 14 }}>{error}</div>}
          <Btn block onClick={submit} disabled={loading}>
            {loading ? 'Un instant…' : 'Valider le nouveau mot de passe'}
          </Btn>
        </Card>
      </div>
    </div>
  );
}

export default function EatFitApp() {
  const [session, setSession] = useState(null); // { accessToken, refreshToken, user }
  const [sessionChecked, setSessionChecked] = useState(false); // évite d'afficher l'écran de connexion pendant la vérification initiale
  const [recoveryToken, setRecoveryToken] = useState(null); // token présent si l'utilisateur arrive via un lien "mot de passe oublié"
  const [recoveryDone, setRecoveryDone] = useState(false);
  const [lang, setLang] = useState('fr');
  const [onboarded, setOnboarded] = useState(false);
  const [tourDone, setTourDone] = useState(false);
  const [profile, setProfile] = useState(initialState.profile);
  const [state, setState] = useState(initialState);
  const [view, setView] = useState('home');
  const [modalContent, setModalContent] = useState(null);
  const [toastMsg, setToastMsg] = useState(null);
  const [dataLoaded, setDataLoaded] = useState(false);
  const [saveFailed, setSaveFailed] = useState(false);


  // Détecte un lien de réinitialisation de mot de passe (Supabase redirige vers l'app avec
  // #access_token=...&type=recovery dans l'URL). Si présent, on affiche l'écran dédié avant
  // même de vérifier une session classique.
  useEffect(() => {
    const hash = window.location.hash;
    if (hash && hash.includes('type=recovery')) {
      const params = new URLSearchParams(hash.replace('#', ''));
      const token = params.get('access_token');
      if (token) setRecoveryToken(token);
    }
  }, []);


  // Au premier chargement, on tente de restaurer une session sauvegardée (reste connecté automatiquement)
  useEffect(() => {
    (async () => {
      const saved = loadSessionFromStorage();
      if (!saved) { setSessionChecked(true); return; }
      try {
        const refreshed = await supabaseRefreshSession(saved.refreshToken);
        setSession({ accessToken: refreshed.access_token, refreshToken: refreshed.refresh_token, user: refreshed.user });
      } catch (e) {
        saveSessionToStorage(null); // session expirée ou invalide : on nettoie et on redemande une connexion
      }
      setSessionChecked(true);
    })();
  }, []);


  // Sauvegarde la session à chaque connexion/déconnexion pour rester connecté d'une visite à l'autre
  useEffect(() => {
    saveSessionToStorage(session);
  }, [session]);


  const toast = (msg) => {
    setToastMsg(msg);
    clearTimeout(window._eatfitToastTimer);
    window._eatfitToastTimer = setTimeout(() => setToastMsg(null), 8000);
  };
  const openModal = (content) => setModalContent(content);
  const closeModal = () => setModalContent(null);
  const navigate = (v) => { setView(v); window.scrollTo(0, 0); };


  // Chargement des données sauvegardées au démarrage — nécessite une session active
  useEffect(() => {
    if (!session) return;
    (async () => {
      try {
        let row = await supabaseFetchUserData(session.accessToken, session.user.id);
        if (!row) row = await supabaseCreateUserRow(session.accessToken, session.user.id);
        if (row) {
          if (row.profile && Object.keys(row.profile).length) setProfile({ ...initialState.profile, ...row.profile });
          if (row.state && Object.keys(row.state).length) {
            setState(s => ({
              ...initialState,
              ...row.state,
              settings: { ...initialState.settings, ...(row.state.settings || {}) }
            }));
          }
          setOnboarded(!!row.onboarded);
          setTourDone(row.tour_done === true || (row.onboarded && row.tour_done !== false));
          if (row.lang) setLang(row.lang);
        }
      } catch (e) {
        // Erreur de chargement : on démarre à zéro pour cette session, silencieusement.
      }
      // Détection automatique de la disponibilité de l'IA : un test léger (timeout 9s, pour tolérer
      // un "cold start" de la fonction serveur Vercel juste après un déploiement) détermine si le
      // mode IA doit être actif ou non, sans jamais demander à l'utilisateur de choisir.
      let aiAvailable = false;
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 9000);
        const testResponse = await fetch("/api/anthropic", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ model: "claude-sonnet-5", max_tokens: 1, thinking: { type: "disabled" }, messages: [{ role: "user", content: "test" }] }),
          signal: controller.signal
        });
        clearTimeout(timeoutId);
        aiAvailable = testResponse.ok;
      } catch (e) {
        aiAvailable = false;
      }
      setState(s => ({ ...s, settings: { ...s.settings, aiMode: aiAvailable } }));
      setDataLoaded(true);
    })();
  }, [session]);


  // Sauvegarde automatique à chaque changement (debounce léger pour éviter le spam d'appels)
  useEffect(() => {
    if (!dataLoaded || !session) return; // ne pas écraser les données avant que le chargement initial soit terminé
    const timer = setTimeout(async () => {
      try {
        const ok = await supabaseSaveUserData(session.accessToken, session.user.id, {
          profile, state, onboarded, tour_done: tourDone, lang, updated_at: new Date().toISOString()
        });
        setSaveFailed(!ok);
      } catch (e) {
        setSaveFailed(true);
      }
    }, 500);
    return () => clearTimeout(timer);
  }, [profile, state, onboarded, tourDone, lang, dataLoaded, session]);


  const finishOnboarding = () => {
    const newProfile = { ...profile };
    const chosenUnits = newProfile.unitsPreference || 'metric';
    delete newProfile.unitsPreference;
    if (newProfile.weight) newProfile.weightHistory = [{ date: todayStr(), weight: newProfile.weight }];
    const cal = calcTargetCalories(newProfile);
    if (cal) { newProfile.targetCalories = cal; newProfile.targetMacros = calcTargetMacros(newProfile, cal); }
    const chosenModules = newProfile.modules && Object.values(newProfile.modules).some(Boolean) ? newProfile.modules : DEFAULT_MODULES;
    setProfile(newProfile);
    setState(s => ({ ...s, profile: newProfile, settings: { ...s.settings, units: chosenUnits, modules: chosenModules } }));
    setOnboarded(true);
    toast(verdict('goalSet_' + newProfile.goal, lang));
  };


  useEffect(() => {
    if (!onboarded || !state.settings.notifsEnabled) return;
    if (typeof Notification === 'undefined') return;


    const checkAndNotify = () => {
      if (Notification.permission !== 'granted') return;
      const lastKey = window._eatfitLastNotifKey;
      const lastDate = window._eatfitLastNotifDate;
      const notifKey = determineContextualNotification(state, lastKey, lastDate);
      if (!notifKey) return;
      const msg = notifMessage(notifKey, lang);
      try {
        new Notification('EATFIT', { body: msg, icon: undefined, tag: 'eatfit-reminder' });
        window._eatfitLastNotifKey = notifKey;
        window._eatfitLastNotifDate = todayStr();
      } catch (e) { /* navigateur ne supporte pas, on ignore silencieusement */ }
    };


    checkAndNotify();
    const onFocus = () => checkAndNotify();
    window.addEventListener('focus', onFocus);
    const interval = setInterval(checkAndNotify, 15 * 60 * 1000);
    return () => { window.removeEventListener('focus', onFocus); clearInterval(interval); };
  }, [onboarded, state.settings.notifsEnabled, state.foodLog, state.workouts, lang]);


  const fabAction = () => {
    if (view === 'pantry') openModal(<AddPantryModal state={state} setState={setState} closeModal={closeModal} toast={toast} />);
    if (view === 'nutrition') openModal(<LogFoodModal state={state} setState={setState} closeModal={closeModal} toast={toast} />);
    if (view === 'workout') openModal(<NewWorkoutModal state={state} setState={setState} closeModal={closeModal} toast={toast} openModal={openModal} />);
  };


  const containerStyle = {
    fontFamily: "'Inter', system-ui, sans-serif",
    background: 'radial-gradient(circle at 50% 0%, rgba(47,158,110,0.08), transparent 45%), radial-gradient(circle at 15% 100%, rgba(58,90,196,0.05), transparent 50%), #131519',
    color: '#eef0f2',
    minHeight: '100vh', maxWidth: 560, margin: '0 auto', position: 'relative', paddingBottom: 88, boxSizing: 'border-box'
  };


  const langContextValue = { lang, t: (key) => t(lang, key) };


  const FlagSelector = () => (
    <div style={{ display: 'flex', gap: 4 }}>
      {[{ code: 'fr', flag: '🇫🇷' }, { code: 'en', flag: '🇬🇧' }, { code: 'es', flag: '🇪🇸' }].map(l => (
        <button key={l.code} onClick={() => setLang(l.code)} style={{
          fontSize: 16, padding: '4px 6px', borderRadius: 6, background: lang === l.code ? 'rgba(47,158,110,0.16)' : 'transparent',
          border: lang === l.code ? '1px solid #2f9e6e' : '1px solid transparent', cursor: 'pointer', opacity: lang === l.code ? 1 : 0.5
        }}>{l.flag}</button>
      ))}
    </div>
  );


  if (recoveryToken && !recoveryDone) {
    return <PasswordResetScreen accessToken={recoveryToken} onDone={() => {
      setRecoveryDone(true);
      setRecoveryToken(null);
      window.history.replaceState(null, '', window.location.pathname);
    }} />;
  }

  if (!sessionChecked) {
    return (
      <div style={{ background: '#131519', minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ fontFamily: "'JetBrains Mono', monospace", color: '#7d8590', fontSize: 13 }}>Chargement…</div>
      </div>
    );
  }


  if (!session) {
    return <AuthScreen onAuthenticated={setSession} />;
  }


  if (!dataLoaded) {
    return (
      <div style={{ ...containerStyle, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ fontFamily: "'JetBrains Mono', monospace", color: '#7d8590', fontSize: 13 }}>Chargement…</div>
      </div>
    );
  }


  if (!onboarded) {
    return (
      <LangContext.Provider value={langContextValue}>
        <div style={containerStyle}>
          <style>{`
            * { box-sizing: border-box; }
            input::placeholder { color: #7d8590; }
            ::-webkit-scrollbar { display: none; }
            .btn-press:active { transform: scale(0.97); }
            @keyframes fadeInUp { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
            .onboard-step { animation: fadeInUp .25s ease; }
          `}</style>
          <div style={{ position: 'absolute', top: 18, right: 20, zIndex: 10 }}><FlagSelector /></div>
          <Onboarding profile={profile} setProfile={setProfile} onFinish={finishOnboarding} />
          {saveFailed && (
            <div style={{ position: 'fixed', top: 0, left: 0, right: 0, zIndex: 300, background: '#4a2020', color: '#ffb4b4', fontSize: 12.5, textAlign: 'center', padding: '8px 12px', fontFamily: "'JetBrains Mono', monospace" }}>
              ⚠ Sauvegarde impossible pour le moment — tes données restent affichées mais risquent de se perdre en fermant l'appli.
            </div>
          )}
        </div>
      </LangContext.Provider>
    );
  }


  if (!tourDone) {
    return (
      <LangContext.Provider value={langContextValue}>
        <div style={containerStyle}>
          <style>{`
            * { box-sizing: border-box; }
            ::-webkit-scrollbar { display: none; }
            .btn-press:active { transform: scale(0.97); }
            @keyframes fadeInUp { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
            .onboard-step { animation: fadeInUp .25s ease; }
          `}</style>
          <GuidedTour lang={lang} profile={profile} onFinish={() => setTourDone(true)} />
        </div>
      </LangContext.Provider>
    );
  }


  const activeModules = state.settings.modules || DEFAULT_MODULES;
  const tabs = [
    { id: 'home', label: t(lang, 'tab_home'), icon: <IconHome /> },
    activeModules.antiGaspi && { id: 'pantry', label: t(lang, 'tab_pantry'), icon: <IconPantry /> },
    activeModules.plan && { id: 'nutrition', label: t(lang, 'tab_nutrition'), icon: <IconNutrition /> },
    (activeModules.antiGaspi || activeModules.plan) && { id: 'courses', label: t(lang, 'tab_shopping_list'), icon: <IconShoppingList /> },
    activeModules.sport && { id: 'workout', label: t(lang, 'tab_workout'), icon: <IconWorkout /> },
    activeModules.sport && { id: 'progress', label: t(lang, 'tab_progress'), icon: <IconProgress /> }
  ].filter(Boolean);


  let viewContent;
  if (view === 'home') viewContent = <HomeView state={state} navigate={navigate} setState={setState} toast={toast} openModal={openModal} closeModal={closeModal} />;
  else if (view === 'pantry') viewContent = <PantryView state={state} setState={setState} navigate={navigate} openModal={openModal} closeModal={closeModal} toast={toast} />;
  else if (view === 'recipes') viewContent = <RecipesView state={state} setState={setState} navigate={navigate} openModal={openModal} closeModal={closeModal} toast={toast} />;
  else if (view === 'nutrition') viewContent = <NutritionView state={state} setState={setState} openModal={openModal} closeModal={closeModal} toast={toast} />;
  else if (view === 'courses') viewContent = <ShoppingListView state={state} setState={setState} openModal={openModal} closeModal={closeModal} toast={toast} />;
  else if (view === 'workout') viewContent = <WorkoutView state={state} setState={setState} openModal={openModal} closeModal={closeModal} toast={toast} />;
  else if (view === 'progress') viewContent = <ProgressView state={state} setState={setState} toast={toast} openModal={openModal} closeModal={closeModal} />;
  else if (view === 'settings') viewContent = <SettingsView state={state} setState={setState} openModal={openModal} closeModal={closeModal} toast={toast} session={session} onLogout={() => setSession(null)} />;


  const showFab = ['pantry', 'nutrition', 'workout'].includes(view);


  return (
    <LangContext.Provider value={langContextValue}>
      <div style={containerStyle}>
        <style>{`
          * { box-sizing: border-box; }
          input::placeholder { color: #7d8590; }
          ::-webkit-scrollbar { display: none; }
          .btn-press:active { transform: scale(0.97); }
          @keyframes fadeInUp { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
          .view-fade { animation: fadeInUp .22s ease; }
          @keyframes popIn { 0% { transform: scale(0.7); } 60% { transform: scale(1.12); } 100% { transform: scale(1); } }
          .check-pop { animation: popIn .22s ease; }
          @keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
        `}</style>


        {saveFailed && (
          <div style={{ position: 'sticky', top: 0, zIndex: 300, background: '#4a2020', color: '#ffb4b4', fontSize: 12.5, textAlign: 'center', padding: '8px 12px', fontFamily: "'JetBrains Mono', monospace" }}>
            ⚠ Sauvegarde impossible pour le moment — tes dernières actions ne sont peut-être pas enregistrées.
          </div>
        )}


        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '18px 20px 16px', position: 'sticky', top: 0, zIndex: 20, background: 'linear-gradient(180deg, #15171a 85%, transparent)', borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
          <div onClick={() => navigate('settings')} style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer' }}>
            <span style={{ width: 9, height: 9, borderRadius: 5, background: '#2f9e6e', display: 'inline-block', boxShadow: '0 0 8px rgba(47,158,110,0.55)' }} />
            <div style={{ fontFamily: "'Oswald', sans-serif", fontSize: 20, fontWeight: 700, letterSpacing: '0.02em' }}>Eat<span style={{ color: '#2f9e6e' }}>Fit</span></div>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <FlagSelector />
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontFamily: "'JetBrains Mono', monospace", fontSize: 13, color: '#ff9a56', background: 'rgba(255,154,86,0.12)', padding: '6px 10px', borderRadius: 20, border: '1px solid #c4502049' }}>
              🔥 {computeStreak(state)}j
            </div>
          </div>
        </div>


        <div key={view} className="view-fade" style={{ padding: '4px 20px 24px' }}>{viewContent}</div>


        <div style={{ position: 'fixed', bottom: 0, left: 0, right: 0, zIndex: 30, background: 'rgba(21,23,26,0.85)', backdropFilter: 'blur(16px)', borderTop: '1px solid rgba(255,255,255,0.06)', display: 'flex', justifyContent: 'center' }}>
          <div style={{ display: 'flex', width: '100%', maxWidth: 560, padding: '6px 8px' }}>
            {tabs.map(tab => (
              <button key={tab.id} onClick={() => navigate(tab.id)} style={{
                flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3, padding: '8px 4px',
                margin: '0 3px', borderRadius: 12,
                color: view === tab.id ? '#2f9e6e' : '#7d8590', fontSize: 10.5, fontFamily: "'JetBrains Mono', monospace",
                textTransform: 'uppercase', letterSpacing: '0.03em', background: view === tab.id ? 'rgba(47,158,110,0.12)' : 'none',
                border: 'none', cursor: 'pointer', transition: 'background .15s, color .15s'
              }}>{tab.icon}<span>{tab.label}</span></button>
            ))}
          </div>
        </div>


        {showFab && (
          <button onClick={fabAction} style={{
            position: 'fixed', right: 20, bottom: 100, zIndex: 25, width: 58, height: 58, borderRadius: '50%',
            background: 'linear-gradient(145deg, #34b483, #2f9e6e)', color: '#07140f', display: 'flex', alignItems: 'center', justifyContent: 'center',
            boxShadow: '0 8px 24px rgba(47,158,110,0.4), 0 0 0 1px rgba(255,255,255,0.08) inset', fontSize: 28, fontWeight: 700, border: 'none', cursor: 'pointer',
            transition: 'transform .15s'
          }}>+</button>
        )}


        {modalContent && <Modal onClose={closeModal} onGoHome={() => { closeModal(); navigate('home'); }}>{modalContent}</Modal>}


        {toastMsg && (
          <div style={{
            position: 'fixed', bottom: 96, left: '50%', transform: 'translateX(-50%)', background: '#262b32',
            border: '1px solid #2f9e6e', borderRadius: 30, padding: '11px 20px', fontSize: 13.5, zIndex: 200,
            maxWidth: '90%', textAlign: 'center', boxShadow: '0 8px 24px rgba(0,0,0,0.4)'
          }}>{toastMsg}</div>
        )}
      </div>
    </LangContext.Provider>
  );
}
